INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C1','math',3,1,'u1',2,'받아올림이 없는 세 자리 수의 덧셈 — 수 모형과 세로셈으로 일·십·백의 자리 수끼리 더하기',ARRAY['4수01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C2','math',3,1,'u1',3,'받아올림이 한 번 있는 세 자리 수의 덧셈 — 한 자리의 합이 10이거나 10보다 크면 10을 윗자리 1로 바꾸어 받아올리고, 받아올림한 1을 윗자리 계산에 더하기',ARRAY['4수01-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C3','math',3,1,'u1',3,'덧셈·뺄셈의 어림 — 계산하기 전에 각 수를 가까운 몇백(몇십)으로 어림해 대강의 값을 가늠하고, 계산한 값과 견주어 점검하기',ARRAY['4수01-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C4','math',3,1,'u1',4,'받아올림이 여러 번 있는 세 자리 수의 덧셈 — 일 → 십 → 백 차례로 받아올림을 모두 표시하고, 합이 1000을 넘으면 천의 자리에 1을 쓰기',ARRAY['4수01-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C5','math',3,1,'u1',5,'받아내림이 없는 세 자리 수의 뺄셈 — 수 모형과 세로셈으로 일·십·백의 자리 수끼리 빼기',ARRAY['4수01-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C6','math',3,1,'u1',6,'받아내림이 한 번 있는 세 자리 수의 뺄셈 — 같은 자리끼리 뺄 수 없으면 윗자리에서 1을 빌려 10으로 바꾸어 빼고, 빌려준 윗자리는 1 줄여 계산하기',ARRAY['4수01-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C7','math',3,1,'u1',7,'받아내림이 여러 번 있는 세 자리 수의 뺄셈 — 받아내림을 두 번 다 표시하고, 0이 있는 자리는 백의 자리에서 빌려 십의 자리 9와 일의 자리 10으로 나누어 계산하기',ARRAY['4수01-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u1-C8','math',3,1,'u1',8,'덧셈과 뺄셈으로 문제 해결 — 모으는 상황은 덧셈, 남은 것·더 많은 것은 뺄셈으로 식을 세우고, 크기를 견주어 판단하며 어림으로 알맞은 것을 고르기',ARRAY['4수01-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X01','math',3,'u1',ARRAY['M3-1-u1-C1','M3-1-u1-C2','M3-1-u1-C4','M3-1-u1-C5','M3-1-u1-C6','M3-1-u1-C7']::text[],'자리를 맞추지 않고 계산한다 — 같은 자리끼리가 아니라 앞자리부터 맞추거나 자리를 밀어 쓴다','일은 일끼리, 십은 십끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X02','math',3,'u1',ARRAY['M3-1-u1-C2','M3-1-u1-C4','M3-1-u1-C8']::text[],'받아올림을 빠뜨린다 — 한 자리의 합에서 10을 버리고 일의 숫자만 쓴다','10이 넘으면 윗자리에 작은 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X03','math',3,'u1',ARRAY['M3-1-u1-C2','M3-1-u1-C4']::text[],'받아올림한 1을 엉뚱한 자리에 더한다(십이 아니라 백에 더한다)','받아올림은 바로 윗자리로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X04','math',3,'u1',ARRAY['M3-1-u1-C2','M3-1-u1-C4']::text[],'한 자리의 합(12)을 그대로 그 자리에 적어 수가 길어진다','한 칸에는 숫자 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X05','math',3,'u1',ARRAY['M3-1-u1-C4']::text[],'받아올림이 여러 번일 때 한 번만 하고 나머지를 빠뜨린다','받아올림을 모두 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X06','math',3,'u1',ARRAY['M3-1-u1-C4']::text[],'합이 1000을 넘을 때 천의 자리 1을 쓰지 않는다','백의 자리에서도 받아올림하면 천의 자리에 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X07','math',3,'u1',ARRAY['M3-1-u1-C6','M3-1-u1-C7']::text[],'뺄 수 없는 자리에서 큰 수에서 작은 수를 거꾸로 뺀다(3 − 8 대신 8 − 3)','위 수가 작으면 윗자리에서 빌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X08','math',3,'u1',ARRAY['M3-1-u1-C6','M3-1-u1-C7']::text[],'받아내림한 뒤 빌려준 윗자리를 1 줄이지 않는다','빌려준 자리는 1 줄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X09','math',3,'u1',ARRAY['M3-1-u1-C7']::text[],'0이 있는 자리에서 받아내림을 잘못한다 — 백에서 빌린 뒤 십의 자리를 9가 아니라 10으로 둔다','100을 90과 10으로 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X10','math',3,'u1',ARRAY['M3-1-u1-C7']::text[],'받아내림이 여러 번일 때 한 번만 줄이고 다음 받아내림의 줄어든 자리를 빠뜨린다','받아내림을 두 번 다 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X11','math',3,'u1',ARRAY['M3-1-u1-C3','M3-1-u1-C8']::text[],'어림할 때 가까운 몇백(몇십)이 아니라 앞자리만 떼어 버리거나 엉뚱한 쪽으로 어림한다','가까운 쪽으로 — 50 이상은 올림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X12','math',3,'u1',ARRAY['M3-1-u1-C8']::text[],'생활 속 문제에서 연산을 잘못 고른다(모두는 덧셈, 남은·더 많은은 뺄셈)','「모두」·「남은」·「몇 더」에 밑줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X13','math',3,'u1',ARRAY['M3-1-u1-C8']::text[],'크기 비교를 거꾸로 하거나 계산하지 않고 앞자리만 보고 판단한다','두 값을 다 계산한 뒤 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X14','math',3,'u1',ARRAY['M3-1-u1-C1','M3-1-u1-C2','M3-1-u1-C3','M3-1-u1-C4','M3-1-u1-C5','M3-1-u1-C6','M3-1-u1-C7','M3-1-u1-C8']::text[],'계산 실수 — 한 자리를 하나 더 세거나 덜 센다(10이나 100만큼 어긋난다)','어림과 견주어 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u1-X15','math',3,'u1',ARRAY['M3-1-u1-C1','M3-1-u1-C2','M3-1-u1-C3','M3-1-u1-C4','M3-1-u1-C5','M3-1-u1-C6','M3-1-u1-C7','M3-1-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 큰↔작은, 남은↔쓴','물음의 「틀린·남은」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#1','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',1,'mc','auto','426 + 342는 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"426 + 342는 얼마인가요?","options":[{"t":"768","correct":true},{"t":"778","mis":"M3-1-u1-X14"},{"t":"758","mis":"M3-1-u1-X14"},{"t":"868","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 2 = 8.","십의 자리: 2 + 4 = 6.","백의 자리: 4 + 3 = 7 — 그래서 426 + 342 = 768이에요."],"variant_rule":{"alt":[{"stem":"365 + 412는 얼마인가요?","options":[{"t":"777","correct":true},{"t":"787","mis":"M3-1-u1-X14"},{"t":"767","mis":"M3-1-u1-X14"},{"t":"877","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 + 2 = 7.","십의 자리: 6 + 1 = 7.","백의 자리: 3 + 4 = 7 — 그래서 365 + 412 = 777이에요."]},{"stem":"552 + 235는 얼마인가요?","options":[{"t":"787","correct":true},{"t":"797","mis":"M3-1-u1-X14"},{"t":"777","mis":"M3-1-u1-X14"},{"t":"887","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 5 = 7.","십의 자리: 5 + 3 = 8.","백의 자리: 5 + 2 = 7 — 그래서 552 + 235 = 787이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#2','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',1,'mc','auto','245는 백 모형 몇 개, 십 모형 몇 개, 일 모형 몇 개인가요?',ARRAY['M3-1-u1-X01','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"245는 백 모형 몇 개, 십 모형 몇 개, 일 모형 몇 개인가요?","options":[{"t":"백 2개, 십 4개, 일 5개","correct":true},{"t":"백 5개, 십 4개, 일 2개","mis":"M3-1-u1-X01"},{"t":"백 2개, 십 45개","mis":"M3-1-u1-X14"},{"t":"백 24개, 일 5개","mis":"M3-1-u1-X14"}],"explanation":["245의 백의 자리 숫자는 2, 십의 자리 숫자는 4, 일의 자리 숫자는 5예요.","백 모형 2개, 십 모형 4개, 일 모형 5개가 모이면 245예요.","자리마다 숫자를 읽어요."],"variant_rule":{"alt":[{"stem":"363은 백 모형 몇 개, 십 모형 몇 개, 일 모형 몇 개인가요?","options":[{"t":"백 3개, 십 6개, 일 3개","correct":true},{"t":"백 6개, 십 3개, 일 3개","mis":"M3-1-u1-X01"},{"t":"백 3개, 십 63개","mis":"M3-1-u1-X14"},{"t":"백 36개, 일 3개","mis":"M3-1-u1-X14"}],"explanation":["백의 자리 3, 십의 자리 6, 일의 자리 3이에요.","백 모형 3개, 십 모형 6개, 일 모형 3개예요.","자리마다 숫자를 읽어요."]},{"stem":"517은 백 모형 몇 개, 십 모형 몇 개, 일 모형 몇 개인가요?","options":[{"t":"백 5개, 십 1개, 일 7개","correct":true},{"t":"백 7개, 십 1개, 일 5개","mis":"M3-1-u1-X01"},{"t":"백 5개, 십 17개","mis":"M3-1-u1-X14"},{"t":"백 51개, 일 7개","mis":"M3-1-u1-X14"}],"explanation":["백의 자리 5, 십의 자리 1, 일의 자리 7이에요.","백 모형 5개, 십 모형 1개, 일 모형 7개예요.","자리마다 숫자를 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#3','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',1,'sa','auto','125 + 352를 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u1-C1","difficulty":1,"kind":"sa","stem":"125 + 352를 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["일의 자리: 5 + 2 = 7.","십의 자리: 2 + 5 = 7.","125 + 352 = 477 — 십의 자리 숫자는 7이에요."],"variant_rule":{"alt":[{"stem":"721 + 208을 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리: 1 + 8 = 9.","십의 자리: 2 + 0 = 2.","721 + 208 = 929 — 십의 자리 숫자는 2예요."]},{"stem":"423 + 202를 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리: 3 + 2 = 5.","십의 자리: 2 + 0 = 2.","423 + 202 = 625 — 십의 자리 숫자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#4','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',1,'mc','auto','581 + 315는 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":4,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"581 + 315는 얼마인가요?","options":[{"t":"896","correct":true},{"t":"906","mis":"M3-1-u1-X14"},{"t":"886","mis":"M3-1-u1-X14"},{"t":"996","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1 + 5 = 6.","십의 자리: 8 + 1 = 9.","백의 자리: 5 + 3 = 8 — 그래서 581 + 315 = 896이에요."],"variant_rule":{"alt":[{"stem":"323 + 303은 얼마인가요?","options":[{"t":"626","correct":true},{"t":"636","mis":"M3-1-u1-X14"},{"t":"616","mis":"M3-1-u1-X14"},{"t":"726","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 3 + 3 = 6.","십의 자리: 2 + 0 = 2.","백의 자리: 3 + 3 = 6 — 그래서 323 + 303 = 626이에요."]},{"stem":"420 + 324는 얼마인가요?","options":[{"t":"744","correct":true},{"t":"754","mis":"M3-1-u1-X14"},{"t":"734","mis":"M3-1-u1-X14"},{"t":"844","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 4 = 4.","십의 자리: 2 + 2 = 4.","백의 자리: 4 + 3 = 7 — 그래서 420 + 324 = 744예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#5','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',2,'mc','auto','도서관에 동화책이 426권, 과학책이 342권 있어요. 책은 모두 몇 권인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":5,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"도서관에 동화책이 426권, 과학책이 342권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"768권","correct":true},{"t":"84권","mis":"M3-1-u1-X12"},{"t":"778권","mis":"M3-1-u1-X14"},{"t":"758권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 426 + 342.","십의 자리: 2 + 4 = 6.","426 + 342 = 768 — 768권이에요."],"variant_rule":{"alt":[{"stem":"도서관에 동화책이 441권, 과학책이 123권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"564권","correct":true},{"t":"318권","mis":"M3-1-u1-X12"},{"t":"574권","mis":"M3-1-u1-X14"},{"t":"554권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 441 + 123.","십의 자리: 4 + 2 = 6.","441 + 123 = 564 — 564권이에요."]},{"stem":"도서관에 동화책이 461권, 과학책이 311권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"772권","correct":true},{"t":"150권","mis":"M3-1-u1-X12"},{"t":"782권","mis":"M3-1-u1-X14"},{"t":"762권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 461 + 311.","십의 자리: 6 + 1 = 7.","461 + 311 = 772 — 772권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#6','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',2,'ox','auto','세 자리 수의 덧셈은 백의 자리부터 더해도 되고, 받아올림이 없으면 어느 자리부터 더해도 답이 같아요.',ARRAY['M3-1-u1-X01']::text[],false,'{"seq":6,"concept":"M3-1-u1-C1","difficulty":2,"kind":"ox","stem":"세 자리 수의 덧셈은 백의 자리부터 더해도 되고, 받아올림이 없으면 어느 자리부터 더해도 답이 같아요.","answer":"O","reason_options":[{"t":"받아올림이 없으면 자리끼리 더한 값이 서로 영향을 주지 않아서","correct":true},{"t":"세 자리 수는 반드시 백의 자리부터 더해야 해서","mis":"M3-1-u1-X01"}],"mis":"M3-1-u1-X01","explanation":["받아올림이 없으면 각 자리의 합이 9를 넘지 않아요.","그래서 어느 자리부터 더해도 같은 답이에요.","받아올림이 있을 때는 일의 자리부터 더해야 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#7','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',2,'match','auto','덧셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u1-C1","difficulty":2,"kind":"match","stem":"덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"636 + 103","r":"739"},{"l":"330 + 305","r":"635"},{"l":"320 + 143","r":"463"}],"mis":"M3-1-u1-X01","explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","636 + 103 = 739, 330 + 305 = 635, 320 + 143 = 463이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"606 + 350","r":"956"},{"l":"702 + 224","r":"926"},{"l":"401 + 395","r":"796"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","606 + 350 = 956, 702 + 224 = 926, 401 + 395 = 796이에요."]},{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"603 + 163","r":"766"},{"l":"330 + 247","r":"577"},{"l":"167 + 522","r":"689"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","603 + 163 = 766, 330 + 247 = 577, 167 + 522 = 689예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#8','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',2,'mc','auto','고구마를 지난달에 672개 캤어요. 이번 달에는 지난달보다 214개 더 캤어요. 이번 달에 캔 고구마는 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":8,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"고구마를 지난달에 672개 캤어요. 이번 달에는 지난달보다 214개 더 캤어요. 이번 달에 캔 고구마는 몇 개인가요?","options":[{"t":"886개","correct":true},{"t":"458개","mis":"M3-1-u1-X12"},{"t":"896개","mis":"M3-1-u1-X14"},{"t":"876개","mis":"M3-1-u1-X14"}],"explanation":["지난번보다 더 많은 수를 구하니 덧셈이에요 — 672 + 214.","십의 자리: 7 + 1 = 8.","672 + 214 = 886 — 886개예요."],"variant_rule":{"alt":[{"stem":"고구마를 지난달에 113개 캤어요. 이번 달에는 지난달보다 423개 더 캤어요. 이번 달에 캔 고구마는 몇 개인가요?","options":[{"t":"536개","correct":true},{"t":"310개","mis":"M3-1-u1-X12"},{"t":"546개","mis":"M3-1-u1-X14"},{"t":"526개","mis":"M3-1-u1-X14"}],"explanation":["지난번보다 더 많은 수를 구하니 덧셈이에요 — 113 + 423.","십의 자리: 1 + 2 = 3.","113 + 423 = 536 — 536개예요."]},{"stem":"고구마를 지난달에 344개 캤어요. 이번 달에는 지난달보다 501개 더 캤어요. 이번 달에 캔 고구마는 몇 개인가요?","options":[{"t":"845개","correct":true},{"t":"157개","mis":"M3-1-u1-X12"},{"t":"855개","mis":"M3-1-u1-X14"},{"t":"835개","mis":"M3-1-u1-X14"}],"explanation":["지난번보다 더 많은 수를 구하니 덧셈이에요 — 344 + 501.","십의 자리: 4 + 0 = 4.","344 + 501 = 845 — 845개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#9','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',2,'mc','auto','세 자리 수의 덧셈을 세로셈으로 할 때 가장 먼저 맞추어 써야 하는 것은 무엇인가요?',ARRAY['M3-1-u1-X01']::text[],false,'{"seq":9,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"세 자리 수의 덧셈을 세로셈으로 할 때 가장 먼저 맞추어 써야 하는 것은 무엇인가요?","options":[{"t":"두 수의 같은 자리","correct":true},{"t":"두 수의 첫 숫자","mis":"M3-1-u1-X01"},{"t":"두 수의 가장 큰 숫자","mis":"M3-1-u1-X01"},{"t":"두 수의 끝 숫자만","mis":"M3-1-u1-X01"}],"explanation":["세로셈은 일의 자리끼리, 십의 자리끼리, 백의 자리끼리 맞추어 써요.","자리를 맞추어야 같은 자리끼리 더할 수 있어요.","자리가 어긋나면 엉뚱한 답이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_basic#10','math',3,1,'u1','L02','g3_1_math_u1_L02_basic','lesson_basic','M3-1-u1-C1',3,'mc','auto','온라인 마을에 오전에 184명, 오후에 213명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":10,"concept":"M3-1-u1-C1","difficulty":3,"kind":"mc","stem":"온라인 마을에 오전에 184명, 오후에 213명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"397명","correct":true},{"t":"29명","mis":"M3-1-u1-X12"},{"t":"407명","mis":"M3-1-u1-X14"},{"t":"387명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 184 + 213.","십의 자리: 8 + 1 = 9.","184 + 213 = 397 — 397명이에요."],"variant_rule":{"alt":[{"stem":"온라인 마을에 오전에 320명, 오후에 318명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"638명","correct":true},{"t":"2명","mis":"M3-1-u1-X12"},{"t":"648명","mis":"M3-1-u1-X14"},{"t":"628명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 320 + 318.","십의 자리: 2 + 1 = 3.","320 + 318 = 638 — 638명이에요."]},{"stem":"온라인 마을에 오전에 301명, 오후에 552명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"853명","correct":true},{"t":"251명","mis":"M3-1-u1-X12"},{"t":"863명","mis":"M3-1-u1-X14"},{"t":"843명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 301 + 552.","십의 자리: 0 + 5 = 5.","301 + 552 = 853 — 853명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#1','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',2,'mc','auto','372 + 412는 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"372 + 412는 얼마인가요?","options":[{"t":"784","correct":true},{"t":"794","mis":"M3-1-u1-X14"},{"t":"774","mis":"M3-1-u1-X14"},{"t":"884","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 2 = 4.","십의 자리: 7 + 1 = 8.","백의 자리: 3 + 4 = 7 — 그래서 372 + 412 = 784예요."],"variant_rule":{"alt":[{"stem":"142 + 143은 얼마인가요?","options":[{"t":"285","correct":true},{"t":"295","mis":"M3-1-u1-X14"},{"t":"275","mis":"M3-1-u1-X14"},{"t":"385","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 3 = 5.","십의 자리: 4 + 4 = 8.","백의 자리: 1 + 1 = 2 — 그래서 142 + 143 = 285예요."]},{"stem":"623 + 133은 얼마인가요?","options":[{"t":"756","correct":true},{"t":"766","mis":"M3-1-u1-X14"},{"t":"746","mis":"M3-1-u1-X14"},{"t":"856","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 3 + 3 = 6.","십의 자리: 2 + 3 = 5.","백의 자리: 6 + 1 = 7 — 그래서 623 + 133 = 756이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#2','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',2,'sa','auto','242 + 236을 세로셈으로 계산하면 백의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u1-C1","difficulty":2,"kind":"sa","stem":"242 + 236을 세로셈으로 계산하면 백의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["일의 자리: 2 + 6 = 8.","십의 자리: 4 + 3 = 7.","242 + 236 = 478 — 백의 자리 숫자는 4예요."],"variant_rule":{"alt":[{"stem":"496 + 103을 세로셈으로 계산하면 백의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리: 6 + 3 = 9.","십의 자리: 9 + 0 = 9.","496 + 103 = 599 — 백의 자리 숫자는 5예요."]},{"stem":"114 + 543을 세로셈으로 계산하면 백의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리: 4 + 3 = 7.","십의 자리: 1 + 4 = 5.","114 + 543 = 657 — 백의 자리 숫자는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#3','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',3,'error','auto','213 + 124를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X01','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C1","difficulty":3,"kind":"error","stem":"213 + 124를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「213과 124를 앞자리부터 맞추어 쓰고 더해서 2253이야.」","correct":true,"mis_target":"M3-1-u1-X01"},{"t":"도윤 — 「일 3 + 4 = 7, 십 1 + 2 = 3, 백 2 + 1 = 3이라 337이야.」","mis":"M3-1-u1-X15"},{"t":"하린 — 「백 모형 3개, 십 모형 3개, 일 모형 7개라 337이야.」","mis":"M3-1-u1-X15"}],"explanation":["세로셈은 같은 자리끼리 맞추어 써요.","213 + 124 = 337이에요.","수아는 자리를 맞추지 않고 썼어요."],"variant_rule":{"alt":[{"stem":"341 + 215를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"수아 — 「341과 215를 앞자리부터 맞추어 쓰고 더해서 5561이야.」","correct":true,"mis_target":"M3-1-u1-X01"},{"t":"도윤 — 「일 1 + 5 = 6, 십 4 + 1 = 5, 백 3 + 2 = 5라 556이야.」","mis":"M3-1-u1-X15"},{"t":"하린 — 「백 모형 5개, 십 모형 5개, 일 모형 6개라 556이야.」","mis":"M3-1-u1-X15"}],"explanation":["같은 자리끼리 맞추어 써요.","341 + 215 = 556이에요.","수아는 자리를 맞추지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
