INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#7','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',3,'mc','auto','□ 안에 알맞은 수를 고르세요. 324 + □ = 768',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":7,"concept":"M3-1-u1-C1","difficulty":3,"kind":"mc","stem":"□ 안에 알맞은 수를 고르세요. 324 + □ = 768","options":[{"t":"444","correct":true},{"t":"1092","mis":"M3-1-u1-X12"},{"t":"434","mis":"M3-1-u1-X14"},{"t":"544","mis":"M3-1-u1-X14"}],"explanation":["768에서 324를 빼면 □를 구할 수 있어요.","일 8 − 4 = 4, 십 6 − 2 = 4, 백 7 − 3 = 4예요.","□ = 444 — 324 + 444 = 768로 맞아요."],"variant_rule":{"alt":[{"stem":"□ 안에 알맞은 수를 고르세요. 152 + □ = 685","options":[{"t":"533","correct":true},{"t":"837","mis":"M3-1-u1-X12"},{"t":"523","mis":"M3-1-u1-X14"},{"t":"633","mis":"M3-1-u1-X14"}],"explanation":["685에서 152를 빼요.","일 5 − 2 = 3, 십 8 − 5 = 3, 백 6 − 1 = 5예요.","□ = 533이에요."]},{"stem":"□ 안에 알맞은 수를 고르세요. 407 + □ = 959","options":[{"t":"552","correct":true},{"t":"1366","mis":"M3-1-u1-X12"},{"t":"542","mis":"M3-1-u1-X14"},{"t":"652","mis":"M3-1-u1-X14"}],"explanation":["959에서 407을 빼요.","일 9 − 7 = 2, 십 5 − 0 = 5, 백 9 − 4 = 5예요.","□ = 552예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#8','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',4,'essay','teacher','도서관에 동화책이 426권, 과학책이 342권 있어요. 책이 모두 몇 권인지 수 모형으로 어떻게 구하는지 자리마다 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C1","difficulty":4,"kind":"essay","stem":"도서관에 동화책이 426권, 과학책이 342권 있어요. 책이 모두 몇 권인지 수 모형으로 어떻게 구하는지 자리마다 설명해 보세요.","answer_guide":{"answer":"예: 426은 백 모형 4개·십 모형 2개·일 모형 6개, 342는 백 모형 3개·십 모형 4개·일 모형 2개이다. 일 모형 6 + 2 = 8개, 십 모형 2 + 4 = 6개, 백 모형 4 + 3 = 7개이므로 모두 768권이다.","scoring_points":["두 수를 수 모형으로 나타냈는가","같은 자리끼리 더했는가","768권을 구했는가"]},"explanation":["두 수를 백·십·일 모형으로 나타내요.","같은 모형끼리 모아요.","모두 768권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#9','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',4,'essay','teacher','수아는 245 + 312를 백의 자리부터, 도윤이는 일의 자리부터 더했어요. 두 친구의 답이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C1","difficulty":4,"kind":"essay","stem":"수아는 245 + 312를 백의 자리부터, 도윤이는 일의 자리부터 더했어요. 두 친구의 답이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 245 + 312는 일 5 + 2 = 7, 십 4 + 1 = 5, 백 2 + 3 = 5로 어느 자리에서도 합이 10을 넘지 않아 받아올림이 없다. 받아올림이 없으면 자리끼리의 합이 다른 자리에 영향을 주지 않으므로 어느 자리부터 더해도 557로 같다.","scoring_points":["자리마다의 합을 구했는가","받아올림이 없음을 밝혔는가","그래서 순서와 상관없이 557이라고 썼는가"]},"explanation":["자리마다 더하면 7, 5, 5예요.","받아올림이 없어요.","그래서 어느 자리부터 더해도 557이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L02_challenge#10','math',3,1,'u1','L02','g3_1_math_u1_L02_challenge','lesson_challenge','M3-1-u1-C1',4,'mc','auto','두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 640 + 156 ○ 953 − 180',ARRAY['M3-1-u1-X13','M3-1-u1-X14','M3-1-u1-X15']::text[],true,'{"seq":10,"concept":"M3-1-u1-C1","difficulty":4,"kind":"mc","stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 640 + 156 ○ 953 − 180","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 640 + 156 = 796.","오른쪽: 953 − 180 = 773.","796 > 773 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 272 + 602 ○ 914 − 185","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 272 + 602 = 874.","오른쪽: 914 − 185 = 729.","874 > 729 — 알맞은 것은 >예요."]},{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 414 + 275 ○ 929 − 253","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 414 + 275 = 689.","오른쪽: 929 − 253 = 676.","689 > 676 — 알맞은 것은 >예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#1','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',1,'mc','auto','234 + 158은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":1,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"234 + 158은 얼마인가요?","options":[{"t":"392","correct":true},{"t":"382","mis":"M3-1-u1-X02"},{"t":"482","mis":"M3-1-u1-X03"},{"t":"3812","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 4 + 8 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 3 + 5 + 1 = 9.","백의 자리: 2 + 1 = 3 — 그래서 234 + 158 = 392예요."],"variant_rule":{"alt":[{"stem":"514 + 456은 얼마인가요?","options":[{"t":"970","correct":true},{"t":"960","mis":"M3-1-u1-X02"},{"t":"1060","mis":"M3-1-u1-X03"},{"t":"9610","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 4 + 6 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 1 + 5 + 1 = 7.","백의 자리: 5 + 4 = 9 — 그래서 514 + 456 = 970이에요."]},{"stem":"166 + 714는 얼마인가요?","options":[{"t":"880","correct":true},{"t":"870","mis":"M3-1-u1-X02"},{"t":"970","mis":"M3-1-u1-X03"},{"t":"8710","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 6 + 4 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 6 + 1 + 1 = 8.","백의 자리: 1 + 7 = 8 — 그래서 166 + 714 = 880이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#2','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',1,'mc','auto','440 + 365는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"440 + 365는 얼마인가요?","options":[{"t":"805","correct":true},{"t":"705","mis":"M3-1-u1-X02"},{"t":"815","mis":"M3-1-u1-X14"},{"t":"795","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 5 = 5.","십의 자리: 4 + 6 = 10 — 백의 자리로 받아올려요.","백의 자리: 4 + 3 + 1 = 8 — 그래서 440 + 365 = 805예요."],"variant_rule":{"alt":[{"stem":"651 + 171은 얼마인가요?","options":[{"t":"822","correct":true},{"t":"722","mis":"M3-1-u1-X02"},{"t":"832","mis":"M3-1-u1-X14"},{"t":"812","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1 + 1 = 2.","십의 자리: 5 + 7 = 12 — 백의 자리로 받아올려요.","백의 자리: 6 + 1 + 1 = 8 — 그래서 651 + 171 = 822예요."]},{"stem":"683 + 236은 얼마인가요?","options":[{"t":"919","correct":true},{"t":"819","mis":"M3-1-u1-X02"},{"t":"929","mis":"M3-1-u1-X14"},{"t":"909","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 3 + 6 = 9.","십의 자리: 8 + 3 = 11 — 백의 자리로 받아올려요.","백의 자리: 6 + 2 + 1 = 9 — 그래서 683 + 236 = 919예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#3','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C3',1,'mc','auto','412 + 285를 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":3,"concept":"M3-1-u1-C3","difficulty":1,"kind":"mc","stem":"412 + 285를 어림하면 약 얼마인가요?","options":[{"t":"약 700","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X14"}],"explanation":["412는 약 400, 285는 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","400 + 300 = 700 — 약 700이에요. 실제 합 697과 비슷해요."],"variant_rule":{"alt":[{"stem":"594 + 340을 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 1000","mis":"M3-1-u1-X11"},{"t":"약 1100","mis":"M3-1-u1-X14"}],"explanation":["594는 약 600, 340은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","600 + 300 = 900 — 약 900이에요. 실제 합 934와 비슷해요."]},{"stem":"439 + 113을 어림하면 약 얼마인가요?","options":[{"t":"약 500","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X14"}],"explanation":["439는 약 400, 113은 약 100으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","400 + 100 = 500 — 약 500이에요. 실제 합 552와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#4','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',1,'sa','auto','257 + 416을 세로셈으로 계산해요. 십의 자리에서는 5 + 1에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":1,"kind":"sa","stem":"257 + 416을 세로셈으로 계산해요. 십의 자리에서는 5 + 1에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["일의 자리: 7 + 6 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 5 + 1 + 1 = 7.","받아올림한 1을 빠뜨리면 6이 되어 틀려요."],"variant_rule":{"alt":[{"stem":"106 + 419를 세로셈으로 계산해요. 십의 자리에서는 0 + 1에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리: 6 + 9 = 15 — 십의 자리로 1을 받아올려요.","십의 자리: 0 + 1 + 1 = 2.","받아올림한 1을 빠뜨리면 1이 되어 틀려요."]},{"stem":"136 + 808을 세로셈으로 계산해요. 십의 자리에서는 3 + 0에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["일의 자리: 6 + 8 = 14 — 십의 자리로 1을 받아올려요.","십의 자리: 3 + 0 + 1 = 4.","받아올림한 1을 빠뜨리면 3이 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#5','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',2,'mc','auto','게시물에 좋아요가 234개, 최고예요가 158개 달렸어요. 반응은 모두 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X02','M3-1-u1-X03']::text[],true,'{"seq":5,"concept":"M3-1-u1-C2","difficulty":2,"kind":"mc","stem":"게시물에 좋아요가 234개, 최고예요가 158개 달렸어요. 반응은 모두 몇 개인가요?","options":[{"t":"392개","correct":true},{"t":"76개","mis":"M3-1-u1-X12"},{"t":"382개","mis":"M3-1-u1-X02"},{"t":"482개","mis":"M3-1-u1-X03"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 234 + 158.","십의 자리: 3 + 5 + 1 = 9.","234 + 158 = 392 — 392개예요."],"variant_rule":{"alt":[{"stem":"게시물에 좋아요가 154개, 최고예요가 526개 달렸어요. 반응은 모두 몇 개인가요?","options":[{"t":"680개","correct":true},{"t":"372개","mis":"M3-1-u1-X12"},{"t":"670개","mis":"M3-1-u1-X02"},{"t":"770개","mis":"M3-1-u1-X03"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 154 + 526.","십의 자리: 5 + 2 + 1 = 8.","154 + 526 = 680 — 680개예요."]},{"stem":"게시물에 좋아요가 538개, 최고예요가 227개 달렸어요. 반응은 모두 몇 개인가요?","options":[{"t":"765개","correct":true},{"t":"311개","mis":"M3-1-u1-X12"},{"t":"755개","mis":"M3-1-u1-X02"},{"t":"855개","mis":"M3-1-u1-X03"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 538 + 227.","십의 자리: 3 + 2 + 1 = 6.","538 + 227 = 765 — 765개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#6','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',2,'ox','auto','608 + 173 = 771이에요.',ARRAY['M3-1-u1-X02']::text[],true,'{"seq":6,"concept":"M3-1-u1-C2","difficulty":2,"kind":"ox","stem":"608 + 173 = 771이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 781이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"mis":"M3-1-u1-X02","explanation":["일의 자리: 8 + 3 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 0 + 7 + 1 = 8.","바른 답은 781이에요. 771은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"187 + 805 = 982예요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 992가 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 7 + 5 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 8 + 0 + 1 = 9.","바른 답은 992예요. 982는 받아올림을 빠뜨린 값이에요."]},{"stem":"127 + 166 = 283이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 293이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 7 + 6 = 13 — 10을 십의 자리로 받아올리고 3을 써요.","십의 자리: 2 + 6 + 1 = 9.","바른 답은 293이에요. 283은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#7','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C3',2,'mc','auto','어림이 무엇인지 바르게 말한 것은 어느 것인가요?',ARRAY['M3-1-u1-X11']::text[],false,'{"seq":7,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"어림이 무엇인지 바르게 말한 것은 어느 것인가요?","options":[{"t":"정확히 계산하기 전에 대강의 값을 미리 알아보는 것","correct":true},{"t":"계산한 값을 정확히 다시 세는 것","mis":"M3-1-u1-X11"},{"t":"가장 큰 자리 숫자만 남기고 버리는 것","mis":"M3-1-u1-X11"},{"t":"두 수 가운데 큰 수만 보는 것","mis":"M3-1-u1-X11"}],"explanation":["어림은 대강의 값을 가늠하는 거예요.","234는 약 230, 158은 약 160 — 합은 약 390이에요.","계산한 392가 어림 390과 비슷하니 잘 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
