INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#9','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',2,'match','auto','덧셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u1-C2","difficulty":2,"kind":"match","stem":"덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"327 + 215","r":"542"},{"l":"322 + 490","r":"812"},{"l":"544 + 371","r":"915"}],"mis":"M3-1-u1-X02","explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","327 + 215 = 542, 322 + 490 = 812, 544 + 371 = 915예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"155 + 251","r":"406"},{"l":"253 + 664","r":"917"},{"l":"235 + 391","r":"626"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","155 + 251 = 406, 253 + 664 = 917, 235 + 391 = 626이에요."]},{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"163 + 827","r":"990"},{"l":"275 + 319","r":"594"},{"l":"182 + 360","r":"542"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","163 + 827 = 990, 275 + 319 = 594, 182 + 360 = 542예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_basic#10','math',3,1,'u1','L03','g3_1_math_u1_L03_basic','lesson_basic','M3-1-u1-C2',3,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X15']::text[],true,'{"seq":10,"concept":"M3-1-u1-C2","difficulty":3,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"158 + 713 = 861","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"180 + 495 = 675","mis":"M3-1-u1-X15"},{"t":"247 + 414 = 661","mis":"M3-1-u1-X15"},{"t":"349 + 623 = 972","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","158 + 713은 받아올림을 하면 871이에요.","861은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"115 + 238 = 343","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"328 + 145 = 473","mis":"M3-1-u1-X15"},{"t":"358 + 402 = 760","mis":"M3-1-u1-X15"},{"t":"762 + 166 = 928","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","115 + 238은 받아올림을 하면 353이에요.","343은 받아올림을 빠뜨린 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"179 + 702 = 871","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"247 + 445 = 692","mis":"M3-1-u1-X15"},{"t":"256 + 271 = 527","mis":"M3-1-u1-X15"},{"t":"537 + 129 = 666","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","179 + 702는 받아올림을 하면 881이에요.","871은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#1','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',2,'mc','auto','149 + 126은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":1,"concept":"M3-1-u1-C2","difficulty":2,"kind":"mc","stem":"149 + 126은 얼마인가요?","options":[{"t":"275","correct":true},{"t":"265","mis":"M3-1-u1-X02"},{"t":"365","mis":"M3-1-u1-X03"},{"t":"2615","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 9 + 6 = 15 — 10을 십의 자리로 받아올리고 5를 써요.","십의 자리: 4 + 2 + 1 = 7.","백의 자리: 1 + 1 = 2 — 그래서 149 + 126 = 275예요."],"variant_rule":{"alt":[{"stem":"391 + 153은 얼마인가요?","options":[{"t":"544","correct":true},{"t":"444","mis":"M3-1-u1-X02"},{"t":"554","mis":"M3-1-u1-X14"},{"t":"534","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1 + 3 = 4.","십의 자리: 9 + 5 = 14 — 백의 자리로 받아올려요.","백의 자리: 3 + 1 + 1 = 5 — 그래서 391 + 153 = 544예요."]},{"stem":"493 + 475는 얼마인가요?","options":[{"t":"968","correct":true},{"t":"868","mis":"M3-1-u1-X02"},{"t":"978","mis":"M3-1-u1-X14"},{"t":"958","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 3 + 5 = 8.","십의 자리: 9 + 7 = 16 — 백의 자리로 받아올려요.","백의 자리: 4 + 4 + 1 = 9 — 그래서 493 + 475 = 968이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#2','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C3',2,'mc','auto','217 + 333을 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"217 + 333을 어림하면 약 얼마인가요?","options":[{"t":"약 500","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X14"}],"explanation":["217은 약 200, 333은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","200 + 300 = 500 — 약 500이에요. 실제 합 550과 비슷해요."],"variant_rule":{"alt":[{"stem":"104 + 726을 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 900","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 1000","mis":"M3-1-u1-X14"}],"explanation":["104는 약 100, 726은 약 700으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","100 + 700 = 800 — 약 800이에요. 실제 합 830과 비슷해요."]},{"stem":"670 + 281을 어림하면 약 얼마인가요?","options":[{"t":"약 1000","correct":true},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 1100","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X11"}],"explanation":["670은 약 700, 281은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","700 + 300 = 1000 — 약 1000이에요. 실제 합 951과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#3','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',3,'error','auto','234 + 158을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X04','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C2","difficulty":3,"kind":"error","stem":"234 + 158을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"예준 — 「일 4 + 8 = 12니까 일의 자리에 12를 써서 3812야.」","correct":true,"mis_target":"M3-1-u1-X04"},{"t":"채윤 — 「일의 자리에 2를 쓰고 십의 자리로 1을 받아올려.」","mis":"M3-1-u1-X15"},{"t":"태오 — 「십의 자리는 3 + 5 + 1 = 9라서 392야.」","mis":"M3-1-u1-X15"}],"explanation":["한 칸에는 숫자를 하나만 써요.","12는 십 1개와 일 2개 — 일의 자리에 2, 십의 자리로 1을 받아올려요.","예준이는 12를 한 칸에 그대로 썼어요."],"variant_rule":{"alt":[{"stem":"327 + 156을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"예준 — 「일 7 + 6 = 13이니까 일의 자리에 13을 써서 4713이야.」","correct":true,"mis_target":"M3-1-u1-X04"},{"t":"채윤 — 「일의 자리에 3을 쓰고 십의 자리로 1을 받아올려.」","mis":"M3-1-u1-X15"},{"t":"태오 — 「십의 자리는 2 + 5 + 1 = 8이라서 483이야.」","mis":"M3-1-u1-X15"}],"explanation":["한 칸에는 숫자 하나.","13은 일의 자리 3, 십의 자리로 1.","예준이는 13을 한 칸에 그대로 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#4','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',3,'ox','auto','272 + 475 = 647이에요.',ARRAY['M3-1-u1-X02']::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":3,"kind":"ox","stem":"272 + 475 = 647이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 747이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"mis":"M3-1-u1-X02","explanation":["일의 자리: 2 + 5 = 7.","십의 자리: 7 + 7 = 14 — 백의 자리로 받아올려요.","바른 답은 747이에요. 647은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"223 + 181 = 304예요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 404가 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 3 + 1 = 4.","십의 자리: 2 + 8 = 10 — 백의 자리로 받아올려요.","바른 답은 404예요. 304는 받아올림을 빠뜨린 값이에요."]},{"stem":"686 + 280 = 866이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 966이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 6 + 0 = 6.","십의 자리: 8 + 8 = 16 — 백의 자리로 받아올려요.","바른 답은 966이에요. 866은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#5','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',3,'mc','auto','두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 192 + 563 ○ 812 − 116',ARRAY['M3-1-u1-X13','M3-1-u1-X14','M3-1-u1-X15']::text[],true,'{"seq":5,"concept":"M3-1-u1-C2","difficulty":3,"kind":"mc","stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 192 + 563 ○ 812 − 116","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 192 + 563 = 755.","오른쪽: 812 − 116 = 696.","755 > 696 — 알맞은 것은 >예요."],"variant_rule":{"alt":[{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 775 + 133 ○ 928 − 169","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 775 + 133 = 908.","오른쪽: 928 − 169 = 759.","908 > 759 — 알맞은 것은 >예요."]},{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 446 + 414 ○ 910 − 146","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 446 + 414 = 860.","오른쪽: 910 − 146 = 764.","860 > 764 — 알맞은 것은 >예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#6','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',3,'mc','auto','딸기를 채원이네 모둠은 422개, 건우네 모둠은 193개 땄어요. 두 모둠이 딴 딸기는 모두 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X02','M3-1-u1-X14']::text[],true,'{"seq":6,"concept":"M3-1-u1-C2","difficulty":3,"kind":"mc","stem":"딸기를 채원이네 모둠은 422개, 건우네 모둠은 193개 땄어요. 두 모둠이 딴 딸기는 모두 몇 개인가요?","options":[{"t":"615개","correct":true},{"t":"229개","mis":"M3-1-u1-X12"},{"t":"515개","mis":"M3-1-u1-X02"},{"t":"625개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 422 + 193.","십의 자리: 2 + 9 = 11 — 백의 자리로 받아올려요.","422 + 193 = 615 — 615개예요."],"variant_rule":{"alt":[{"stem":"딸기를 채원이네 모둠은 233개, 건우네 모둠은 595개 땄어요. 두 모둠이 딴 딸기는 모두 몇 개인가요?","options":[{"t":"828개","correct":true},{"t":"362개","mis":"M3-1-u1-X12"},{"t":"728개","mis":"M3-1-u1-X02"},{"t":"838개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 233 + 595.","십의 자리: 3 + 9 = 12 — 백의 자리로 받아올려요.","233 + 595 = 828 — 828개예요."]},{"stem":"딸기를 채원이네 모둠은 170개, 건우네 모둠은 779개 땄어요. 두 모둠이 딴 딸기는 모두 몇 개인가요?","options":[{"t":"949개","correct":true},{"t":"609개","mis":"M3-1-u1-X12"},{"t":"849개","mis":"M3-1-u1-X02"},{"t":"959개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 170 + 779.","십의 자리: 7 + 7 = 14 — 백의 자리로 받아올려요.","170 + 779 = 949 — 949개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#7','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C3',3,'mc','auto','412 + 285를 계산했더니 897이 나왔어요. 어림으로 점검하면 어떤가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X15','M3-1-u1-X13']::text[],true,'{"seq":7,"concept":"M3-1-u1-C3","difficulty":3,"kind":"mc","stem":"412 + 285를 계산했더니 897이 나왔어요. 어림으로 점검하면 어떤가요?","options":[{"t":"약 700과 너무 달라 다시 계산해야 한다","correct":true},{"t":"약 900과 비슷하니 맞다","mis":"M3-1-u1-X11"},{"t":"어림으로는 알 수 없다","mis":"M3-1-u1-X15"},{"t":"897이 700보다 크니 맞다","mis":"M3-1-u1-X13"}],"explanation":["412는 약 400, 285는 약 300 — 합은 약 700이에요.","897은 약 700과 200이나 차이 나요.","다시 계산하면 412 + 285 = 697이에요."],"variant_rule":{"alt":[{"stem":"518 + 271을 계산했더니 989가 나왔어요. 어림으로 점검하면 어떤가요?","options":[{"t":"약 800과 너무 달라 다시 계산해야 한다","correct":true},{"t":"약 1000과 비슷하니 맞다","mis":"M3-1-u1-X11"},{"t":"어림으로는 알 수 없다","mis":"M3-1-u1-X15"},{"t":"989가 800보다 크니 맞다","mis":"M3-1-u1-X13"}],"explanation":["518은 약 500, 271은 약 300 — 약 800이에요.","989는 약 800과 많이 달라요.","다시 계산하면 789예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#8','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',4,'essay','teacher','234 + 158을 수 모형으로 계산할 때 일 모형이 12개가 돼요. 이때 어떻게 하는지와 십의 자리 계산에서 조심할 점을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C2","difficulty":4,"kind":"essay","stem":"234 + 158을 수 모형으로 계산할 때 일 모형이 12개가 돼요. 이때 어떻게 하는지와 십의 자리 계산에서 조심할 점을 설명해 보세요.","answer_guide":{"answer":"예: 일 모형 12개 가운데 10개를 묶어 십 모형 1개로 바꾸고 일의 자리에는 2를 쓴다(받아올림). 십의 자리는 3 + 5에 받아올림한 1을 더해 9가 되므로 1을 빠뜨리지 않아야 한다. 백의 자리는 2 + 1 = 3이라 392이다.","scoring_points":["10개를 십 모형 1개로 바꾼다고 썼는가","십의 자리에 받아올림한 1을 더한다고 썼는가","392를 구했는가"]},"explanation":["일 모형 10개 = 십 모형 1개예요.","십의 자리에 받아올림한 1을 더해요.","234 + 158 = 392예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#9','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C3',4,'essay','teacher','게시물에 좋아요 234개, 최고예요 158개가 달렸어요. 계산하기 전에 어림하는 방법과, 어림한 값을 계산한 값과 견주면 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C3","difficulty":4,"kind":"essay","stem":"게시물에 좋아요 234개, 최고예요 158개가 달렸어요. 계산하기 전에 어림하는 방법과, 어림한 값을 계산한 값과 견주면 좋은 점을 써 보세요.","answer_guide":{"answer":"예: 234는 약 230, 158은 약 160으로 어림하면 합은 약 390이다. 계산한 값 392가 어림한 값과 비슷하니 계산이 맞는지 점검할 수 있고, 크게 다르면 받아올림을 빠뜨렸는지 다시 볼 수 있다.","scoring_points":["각 수를 가까운 몇십(몇백)으로 어림했는가","어림한 합을 구했는가","계산이 맞는지 점검할 수 있다고 썼는가"]},"explanation":["234는 약 230, 158은 약 160이에요.","어림한 합은 약 390이에요.","계산한 392와 비슷하니 잘 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L03_challenge#10','math',3,1,'u1','L03','g3_1_math_u1_L03_challenge','lesson_challenge','M3-1-u1-C2',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X15']::text[],true,'{"seq":10,"concept":"M3-1-u1-C2","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"182 + 734 = 816","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"495 + 213 = 708","mis":"M3-1-u1-X15"},{"t":"254 + 438 = 692","mis":"M3-1-u1-X15"},{"t":"274 + 380 = 654","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","182 + 734는 받아올림을 하면 916이에요.","816은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"298 + 631 = 829","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"332 + 271 = 603","mis":"M3-1-u1-X15"},{"t":"212 + 692 = 904","mis":"M3-1-u1-X15"},{"t":"364 + 416 = 780","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","298 + 631은 받아올림을 하면 929예요.","829는 받아올림을 빠뜨린 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"391 + 275 = 566","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"506 + 376 = 882","mis":"M3-1-u1-X15"},{"t":"246 + 191 = 437","mis":"M3-1-u1-X15"},{"t":"453 + 271 = 724","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","391 + 275는 받아올림을 하면 666이에요.","566은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#1','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',1,'mc','auto','347 + 285는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"347 + 285는 얼마인가요?","options":[{"t":"632","correct":true},{"t":"522","mis":"M3-1-u1-X02"},{"t":"532","mis":"M3-1-u1-X05"},{"t":"642","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 + 5 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 4 + 8 + 1 = 13 — 백의 자리로 받아올려요.","백의 자리: 3 + 2 + 1 = 6 — 그래서 347 + 285 = 632예요."],"variant_rule":{"alt":[{"stem":"755 + 186은 얼마인가요?","options":[{"t":"941","correct":true},{"t":"831","mis":"M3-1-u1-X02"},{"t":"841","mis":"M3-1-u1-X05"},{"t":"951","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 + 6 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 5 + 8 + 1 = 14 — 백의 자리로 받아올려요.","백의 자리: 7 + 1 + 1 = 9 — 그래서 755 + 186 = 941이에요."]},{"stem":"666 + 186은 얼마인가요?","options":[{"t":"852","correct":true},{"t":"742","mis":"M3-1-u1-X02"},{"t":"752","mis":"M3-1-u1-X05"},{"t":"862","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 6 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 6 + 8 + 1 = 15 — 백의 자리로 받아올려요.","백의 자리: 6 + 1 + 1 = 8 — 그래서 666 + 186 = 852예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#2','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',1,'mc','auto','158 + 365는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"158 + 365는 얼마인가요?","options":[{"t":"523","correct":true},{"t":"413","mis":"M3-1-u1-X02"},{"t":"423","mis":"M3-1-u1-X05"},{"t":"533","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 + 5 = 13 — 10을 십의 자리로 받아올리고 3을 써요.","십의 자리: 5 + 6 + 1 = 12 — 백의 자리로 받아올려요.","백의 자리: 1 + 3 + 1 = 5 — 그래서 158 + 365 = 523이에요."],"variant_rule":{"alt":[{"stem":"696 + 197은 얼마인가요?","options":[{"t":"893","correct":true},{"t":"783","mis":"M3-1-u1-X02"},{"t":"793","mis":"M3-1-u1-X05"},{"t":"903","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 7 = 13 — 10을 십의 자리로 받아올리고 3을 써요.","십의 자리: 9 + 9 + 1 = 19 — 백의 자리로 받아올려요.","백의 자리: 6 + 1 + 1 = 8 — 그래서 696 + 197 = 893이에요."]},{"stem":"248 + 173은 얼마인가요?","options":[{"t":"421","correct":true},{"t":"311","mis":"M3-1-u1-X02"},{"t":"321","mis":"M3-1-u1-X05"},{"t":"431","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 + 3 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 4 + 7 + 1 = 12 — 백의 자리로 받아올려요.","백의 자리: 2 + 1 + 1 = 4 — 그래서 248 + 173 = 421이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#3','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',1,'sa','auto','216 + 495를 세로셈으로 계산해요. 십의 자리에서는 1 + 9에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u1-C4","difficulty":1,"kind":"sa","stem":"216 + 495를 세로셈으로 계산해요. 십의 자리에서는 1 + 9에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["일의 자리: 6 + 5 = 11 — 십의 자리로 1을 받아올려요.","십의 자리: 1 + 9 + 1 = 11.","받아올림한 1을 빠뜨리면 10이 되어 틀려요."],"variant_rule":{"alt":[{"stem":"238 + 688을 세로셈으로 계산해요. 십의 자리에서는 3 + 8에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["일의 자리: 8 + 8 = 16 — 십의 자리로 1을 받아올려요.","십의 자리: 3 + 8 + 1 = 12.","받아올림한 1을 빠뜨리면 11이 되어 틀려요."]},{"stem":"456 + 144를 세로셈으로 계산해요. 십의 자리에서는 5 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["일의 자리: 6 + 4 = 10 — 십의 자리로 1을 받아올려요.","십의 자리: 5 + 4 + 1 = 10.","받아올림한 1을 빠뜨리면 9가 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#4','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',1,'mc','auto','823 + 679는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X06']::text[],true,'{"seq":4,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"823 + 679는 얼마인가요?","options":[{"t":"1502","correct":true},{"t":"492","mis":"M3-1-u1-X02"},{"t":"1402","mis":"M3-1-u1-X05"},{"t":"502","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 3 + 9 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 2 + 7 + 1 = 10 — 백의 자리로 받아올려요.","백의 자리: 8 + 6 + 1 = 15 — 그래서 823 + 679 = 1502예요."],"variant_rule":{"alt":[{"stem":"406 + 954는 얼마인가요?","options":[{"t":"1360","correct":true},{"t":"350","mis":"M3-1-u1-X02"},{"t":"1350","mis":"M3-1-u1-X05"},{"t":"360","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 6 + 4 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 0 + 5 + 1 = 6.","백의 자리: 4 + 9 = 13 — 그래서 406 + 954 = 1360이에요."]},{"stem":"894 + 821은 얼마인가요?","options":[{"t":"1715","correct":true},{"t":"615","mis":"M3-1-u1-X02"},{"t":"1615","mis":"M3-1-u1-X05"},{"t":"715","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 4 + 1 = 5.","십의 자리: 9 + 2 = 11 — 백의 자리로 받아올려요.","백의 자리: 8 + 8 + 1 = 17 — 그래서 894 + 821 = 1715예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#5','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',2,'mc','auto','빵집에서 빵을 오전에 268개, 오후에 475개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X02','M3-1-u1-X05']::text[],true,'{"seq":5,"concept":"M3-1-u1-C4","difficulty":2,"kind":"mc","stem":"빵집에서 빵을 오전에 268개, 오후에 475개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"743개","correct":true},{"t":"207개","mis":"M3-1-u1-X12"},{"t":"633개","mis":"M3-1-u1-X02"},{"t":"643개","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 268 + 475.","십의 자리: 6 + 7 + 1 = 14 — 백의 자리로 받아올려요.","268 + 475 = 743 — 743개예요."],"variant_rule":{"alt":[{"stem":"빵집에서 빵을 오전에 273개, 오후에 537개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"810개","correct":true},{"t":"264개","mis":"M3-1-u1-X12"},{"t":"700개","mis":"M3-1-u1-X02"},{"t":"710개","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 273 + 537.","십의 자리: 7 + 3 + 1 = 11 — 백의 자리로 받아올려요.","273 + 537 = 810 — 810개예요."]},{"stem":"빵집에서 빵을 오전에 587개, 오후에 333개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"920개","correct":true},{"t":"254개","mis":"M3-1-u1-X12"},{"t":"810개","mis":"M3-1-u1-X02"},{"t":"820개","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 587 + 333.","십의 자리: 8 + 3 + 1 = 12 — 백의 자리로 받아올려요.","587 + 333 = 920 — 920개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#6','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C3',2,'mc','auto','506 + 288을 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":6,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"506 + 288을 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X11"},{"t":"약 1000","mis":"M3-1-u1-X14"}],"explanation":["506은 약 500, 288은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","500 + 300 = 800 — 약 800이에요. 실제 합 794와 비슷해요."],"variant_rule":{"alt":[{"stem":"669 + 183을 어림하면 약 얼마인가요?","options":[{"t":"약 900","correct":true},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 1000","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X11"}],"explanation":["669는 약 700, 183은 약 200으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","700 + 200 = 900 — 약 900이에요. 실제 합 852와 비슷해요."]},{"stem":"165 + 397을 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X11"}],"explanation":["165는 약 200, 397은 약 400으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","200 + 400 = 600 — 약 600이에요. 실제 합 562와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#7','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',2,'ox','auto','세 자리 수끼리 더하면 합은 언제나 세 자리 수예요.',ARRAY['M3-1-u1-X06']::text[],false,'{"seq":7,"concept":"M3-1-u1-C4","difficulty":2,"kind":"ox","stem":"세 자리 수끼리 더하면 합은 언제나 세 자리 수예요.","answer":"X","reason_options":[{"t":"백의 자리에서도 받아올림이 생기면 합이 1000을 넘어 네 자리 수가 되어서","correct":true},{"t":"세 자리 수끼리 더하면 999를 넘을 수 없어서","mis":"M3-1-u1-X06"}],"mis":"M3-1-u1-X06","explanation":["823 + 679에서 백의 자리는 8 + 6 + 1 = 15예요.","천의 자리에 1을 써서 1502가 돼요.","합이 1000을 넘으면 네 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_basic#8','math',3,1,'u1','L04','g3_1_math_u1_L04_basic','lesson_basic','M3-1-u1-C4',2,'match','auto','덧셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u1-C4","difficulty":2,"kind":"match","stem":"덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"539 + 265","r":"804"},{"l":"162 + 598","r":"760"},{"l":"296 + 564","r":"860"}],"mis":"M3-1-u1-X02","explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","539 + 265 = 804, 162 + 598 = 760, 296 + 564 = 860이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"579 + 168","r":"747"},{"l":"349 + 293","r":"642"},{"l":"567 + 245","r":"812"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","579 + 168 = 747, 349 + 293 = 642, 567 + 245 = 812예요."]},{"stem":"이번에는 다른 수예요. 덧셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"308 + 293","r":"601"},{"l":"362 + 358","r":"720"},{"l":"376 + 376","r":"752"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 더해요.","받아올림한 1을 윗자리에 더해요.","308 + 293 = 601, 362 + 358 = 720, 376 + 376 = 752예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
