INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#1','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',2,'mc','auto','688 + 956은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X06']::text[],true,'{"seq":1,"concept":"M3-1-u1-C4","difficulty":2,"kind":"mc","stem":"688 + 956은 얼마인가요?","options":[{"t":"1644","correct":true},{"t":"534","mis":"M3-1-u1-X02"},{"t":"1544","mis":"M3-1-u1-X05"},{"t":"644","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 8 + 6 = 14 — 10을 십의 자리로 받아올리고 4를 써요.","십의 자리: 8 + 5 + 1 = 14 — 백의 자리로 받아올려요.","백의 자리: 6 + 9 + 1 = 16 — 그래서 688 + 956 = 1644예요."],"variant_rule":{"alt":[{"stem":"567 + 793은 얼마인가요?","options":[{"t":"1360","correct":true},{"t":"250","mis":"M3-1-u1-X02"},{"t":"1260","mis":"M3-1-u1-X05"},{"t":"360","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 7 + 3 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 6 + 9 + 1 = 16 — 백의 자리로 받아올려요.","백의 자리: 5 + 7 + 1 = 13 — 그래서 567 + 793 = 1360이에요."]},{"stem":"538 + 592는 얼마인가요?","options":[{"t":"1130","correct":true},{"t":"20","mis":"M3-1-u1-X02"},{"t":"1030","mis":"M3-1-u1-X05"},{"t":"130","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 8 + 2 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 3 + 9 + 1 = 13 — 백의 자리로 받아올려요.","백의 자리: 5 + 5 + 1 = 11 — 그래서 538 + 592 = 1130이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#2','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',2,'sa','auto','198 + 123을 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u1-C4","difficulty":2,"kind":"sa","stem":"198 + 123을 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["일의 자리: 8 + 3 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 9 + 2 + 1 = 12 — 백의 자리로 받아올려요.","198 + 123 = 321 — 십의 자리 숫자는 2예요."],"variant_rule":{"alt":[{"stem":"243 + 468을 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["일의 자리: 3 + 8 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 4 + 6 + 1 = 11 — 백의 자리로 받아올려요.","243 + 468 = 711 — 십의 자리 숫자는 1이에요."]},{"stem":"486 + 475를 세로셈으로 계산하면 십의 자리에 쓰는 숫자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리: 6 + 5 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 8 + 7 + 1 = 16 — 백의 자리로 받아올려요.","486 + 475 = 961 — 십의 자리 숫자는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#3','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',3,'error','auto','347 + 285를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X05','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C4","difficulty":3,"kind":"error","stem":"347 + 285를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「일의 자리에서만 받아올리면 돼서 532야.」","correct":true,"mis_target":"M3-1-u1-X05"},{"t":"서아 — 「일의 자리에서 한 번, 십의 자리에서 또 한 번 받아올려.」","mis":"M3-1-u1-X15"},{"t":"지호 — 「받아올림을 두 번 다 표시하면 632야.」","mis":"M3-1-u1-X15"}],"explanation":["일 7 + 5 = 12 — 십으로 1을 받아올려요.","십 4 + 8 + 1 = 13 — 백으로 또 1을 받아올려요.","민준이는 두 번째 받아올림을 빠뜨렸어요. 바른 답은 632예요."],"variant_rule":{"alt":[{"stem":"268 + 475를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준 — 「일의 자리에서만 받아올리면 돼서 643이야.」","correct":true,"mis_target":"M3-1-u1-X05"},{"t":"서아 — 「일의 자리에서 한 번, 십의 자리에서 또 한 번 받아올려.」","mis":"M3-1-u1-X15"},{"t":"지호 — 「받아올림을 두 번 다 표시하면 743이야.」","mis":"M3-1-u1-X15"}],"explanation":["일 8 + 5 = 13 — 십으로 1.","십 6 + 7 + 1 = 14 — 백으로 또 1.","민준이는 두 번째 받아올림을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
