INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#7','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',3,'mc','auto','온라인 마을에 오전에 959명, 오후에 258명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X02','M3-1-u1-X05']::text[],true,'{"seq":7,"concept":"M3-1-u1-C4","difficulty":3,"kind":"mc","stem":"온라인 마을에 오전에 959명, 오후에 258명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"1217명","correct":true},{"t":"701명","mis":"M3-1-u1-X12"},{"t":"107명","mis":"M3-1-u1-X02"},{"t":"1117명","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 959 + 258.","십의 자리: 5 + 5 + 1 = 11 — 백의 자리로 받아올려요.","959 + 258 = 1217 — 1217명이에요."],"variant_rule":{"alt":[{"stem":"온라인 마을에 오전에 957명, 오후에 858명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"1815명","correct":true},{"t":"99명","mis":"M3-1-u1-X12"},{"t":"705명","mis":"M3-1-u1-X02"},{"t":"1715명","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 957 + 858.","십의 자리: 5 + 5 + 1 = 11 — 백의 자리로 받아올려요.","957 + 858 = 1815 — 1815명이에요."]},{"stem":"온라인 마을에 오전에 529명, 오후에 857명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"1386명","correct":true},{"t":"328명","mis":"M3-1-u1-X12"},{"t":"376명","mis":"M3-1-u1-X02"},{"t":"1376명","mis":"M3-1-u1-X05"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 529 + 857.","십의 자리: 2 + 5 + 1 = 8.","529 + 857 = 1386 — 1386명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#8','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',4,'essay','teacher','347 + 285를 계산하는 과정을 일 → 십 → 백의 자리 차례로 쓰고, 받아올림이 몇 번 일어나는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C4","difficulty":4,"kind":"essay","stem":"347 + 285를 계산하는 과정을 일 → 십 → 백의 자리 차례로 쓰고, 받아올림이 몇 번 일어나는지 설명해 보세요.","answer_guide":{"answer":"예: 일 7 + 5 = 12 → 일의 자리에 2, 십으로 1 받아올림. 십 4 + 8 + 1 = 13 → 십의 자리에 3, 백으로 1 받아올림. 백 3 + 2 + 1 = 6. 그래서 632이고 받아올림은 두 번 일어난다.","scoring_points":["일·십·백 차례로 계산했는가","받아올림 두 번을 밝혔는가","632를 구했는가"]},"explanation":["일 12 → 2를 쓰고 1을 올려요.","십 13 → 3을 쓰고 1을 올려요.","백 6 — 632, 받아올림 두 번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#9','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',4,'essay','teacher','823 + 679의 합이 왜 네 자리 수가 되는지 백의 자리 계산을 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C4","difficulty":4,"kind":"essay","stem":"823 + 679의 합이 왜 네 자리 수가 되는지 백의 자리 계산을 들어 설명해 보세요.","answer_guide":{"answer":"예: 일 3 + 9 = 12, 십 2 + 7 + 1 = 10으로 두 번 받아올림이 있고, 백의 자리는 8 + 6 + 1 = 15가 된다. 15는 백의 자리에 5를 쓰고 천의 자리로 1을 받아올리므로 합은 1502, 네 자리 수가 된다.","scoring_points":["백의 자리 8 + 6 + 1 = 15를 썼는가","천의 자리로 받아올린다고 썼는가","1502를 구했는가"]},"explanation":["백의 자리는 8 + 6 + 1 = 15예요.","천의 자리에 1을 써요.","823 + 679 = 1502예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L04_challenge#10','math',3,1,'u1','L04','g3_1_math_u1_L04_challenge','lesson_challenge','M3-1-u1-C4',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X15']::text[],true,'{"seq":10,"concept":"M3-1-u1-C4","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"548 + 525 = 63","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"265 + 238 = 503","mis":"M3-1-u1-X15"},{"t":"465 + 178 = 643","mis":"M3-1-u1-X15"},{"t":"286 + 377 = 663","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","548 + 525는 받아올림을 하면 1073이에요.","63은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"856 + 279 = 25","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"652 + 258 = 910","mis":"M3-1-u1-X15"},{"t":"189 + 112 = 301","mis":"M3-1-u1-X15"},{"t":"526 + 188 = 714","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","856 + 279는 받아올림을 하면 1135예요.","25는 받아올림을 빠뜨린 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"584 + 456 = 930","correct":true,"mis_target":"M3-1-u1-X02"},{"t":"155 + 486 = 641","mis":"M3-1-u1-X15"},{"t":"275 + 435 = 710","mis":"M3-1-u1-X15"},{"t":"494 + 207 = 701","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","584 + 456은 받아올림을 하면 1040이에요.","930은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
