INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#2','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',2,'mc','auto','드론이 499대 있었어요. 그중 365대가 날아갔어요. 남은 드론은 몇 대인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C5","difficulty":2,"kind":"mc","stem":"드론이 499대 있었어요. 그중 365대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"134대","correct":true},{"t":"864대","mis":"M3-1-u1-X12"},{"t":"144대","mis":"M3-1-u1-X14"},{"t":"124대","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 499 − 365.","일의 자리: 9 − 5 = 4.","499 − 365 = 134 — 134대예요."],"variant_rule":{"alt":[{"stem":"드론이 361대 있었어요. 그중 250대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"111대","correct":true},{"t":"611대","mis":"M3-1-u1-X12"},{"t":"121대","mis":"M3-1-u1-X14"},{"t":"101대","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 361 − 250.","일의 자리: 1 − 0 = 1.","361 − 250 = 111 — 111대예요."]},{"stem":"드론이 448대 있었어요. 그중 331대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"117대","correct":true},{"t":"779대","mis":"M3-1-u1-X12"},{"t":"127대","mis":"M3-1-u1-X14"},{"t":"107대","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 448 − 331.","일의 자리: 8 − 1 = 7.","448 − 331 = 117 — 117대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#3','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',3,'error','auto','456 − 123을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C5","difficulty":3,"kind":"error","stem":"456 − 123을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하은 — 「456과 123을 더해서 579야.」","correct":true,"mis_target":"M3-1-u1-X12"},{"t":"지안 — 「일 6 − 3 = 3, 십 5 − 2 = 3, 백 4 − 1 = 3이라 333이야.」","mis":"M3-1-u1-X15"},{"t":"현우 — 「456에서 123만큼 덜어 내면 333이 남아.」","mis":"M3-1-u1-X15"}],"explanation":["「−」는 빼기예요.","456 − 123 = 333이에요.","하은이는 빼야 할 것을 더했어요."],"variant_rule":{"alt":[{"stem":"578 − 245를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하은 — 「578과 245를 더해서 823이야.」","correct":true,"mis_target":"M3-1-u1-X12"},{"t":"지안 — 「일 8 − 5 = 3, 십 7 − 4 = 3, 백 5 − 2 = 3이라 333이야.」","mis":"M3-1-u1-X15"},{"t":"현우 — 「578에서 245만큼 덜어 내면 333이 남아.」","mis":"M3-1-u1-X15"}],"explanation":["「−」는 빼기예요.","578 − 245 = 333이에요.","하은이는 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
