INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#7','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',3,'mc','auto','두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 160 + 236 ○ 714 − 253',ARRAY['M3-1-u1-X13','M3-1-u1-X14','M3-1-u1-X15']::text[],true,'{"seq":7,"concept":"M3-1-u1-C5","difficulty":3,"kind":"mc","stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 160 + 236 ○ 714 − 253","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 160 + 236 = 396.","오른쪽: 714 − 253 = 461.","396 < 461 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 461 + 336 ○ 933 − 240","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 461 + 336 = 797.","오른쪽: 933 − 240 = 693.","797 > 693 — 알맞은 것은 >예요."]},{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 367 + 412 ○ 864 − 159","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 367 + 412 = 779.","오른쪽: 864 − 159 = 705.","779 > 705 — 알맞은 것은 >예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#8','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',4,'essay','teacher','온라인 마을 아바타 327명 가운데 214명이 이름을 바꿨어요. 이름을 바꾸지 않은 아바타가 몇 명인지 식을 세우고, 자리마다 계산하는 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C5","difficulty":4,"kind":"essay","stem":"온라인 마을 아바타 327명 가운데 214명이 이름을 바꿨어요. 이름을 바꾸지 않은 아바타가 몇 명인지 식을 세우고, 자리마다 계산하는 과정을 써 보세요.","answer_guide":{"answer":"예: 전체에서 바꾼 수를 덜어 내므로 327 − 214이다. 일 7 − 4 = 3, 십 2 − 1 = 1, 백 3 − 2 = 1이라 113명이다.","scoring_points":["327 − 214로 식을 세웠는가","자리마다 뺐는가","113명을 구했는가"]},"explanation":["남은 것을 구하니 뺄셈 327 − 214예요.","일 3, 십 1, 백 1이에요.","113명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#9','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',4,'essay','teacher','757 − 432 = 325가 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C5","difficulty":4,"kind":"essay","stem":"757 − 432 = 325가 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 뺄셈의 답 325에 뺀 수 432를 더해 처음 수 757이 되면 맞다. 325 + 432 = 757이므로 바르게 계산했다.","scoring_points":["차와 뺀 수를 더한다고 썼는가","325 + 432 = 757을 계산했는가","맞다고 판단했는가"]},"explanation":["차 + 빼는 수 = 처음 수예요.","325 + 432 = 757이에요.","그래서 맞게 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L05_challenge#10','math',3,1,'u1','L05','g3_1_math_u1_L05_challenge','lesson_challenge','M3-1-u1-C5',4,'mc','auto','게시판의 댓글 688개 가운데 예절에 어긋난 댓글 432개를 지웠어요. 남은 댓글은 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":10,"concept":"M3-1-u1-C5","difficulty":4,"kind":"mc","stem":"게시판의 댓글 688개 가운데 예절에 어긋난 댓글 432개를 지웠어요. 남은 댓글은 몇 개인가요?","options":[{"t":"256개","correct":true},{"t":"1120개","mis":"M3-1-u1-X12"},{"t":"266개","mis":"M3-1-u1-X14"},{"t":"246개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 688 − 432.","일의 자리: 8 − 2 = 6.","688 − 432 = 256 — 256개예요."],"variant_rule":{"alt":[{"stem":"게시판의 댓글 297개 가운데 예절에 어긋난 댓글 143개를 지웠어요. 남은 댓글은 몇 개인가요?","options":[{"t":"154개","correct":true},{"t":"440개","mis":"M3-1-u1-X12"},{"t":"164개","mis":"M3-1-u1-X14"},{"t":"144개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 297 − 143.","일의 자리: 7 − 3 = 4.","297 − 143 = 154 — 154개예요."]},{"stem":"게시판의 댓글 677개 가운데 예절에 어긋난 댓글 266개를 지웠어요. 남은 댓글은 몇 개인가요?","options":[{"t":"411개","correct":true},{"t":"943개","mis":"M3-1-u1-X12"},{"t":"421개","mis":"M3-1-u1-X14"},{"t":"401개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 677 − 266.","일의 자리: 7 − 6 = 1.","677 − 266 = 411 — 411개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#1','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C6',1,'mc','auto','453 − 138은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"453 − 138은 얼마인가요?","options":[{"t":"315","correct":true},{"t":"325","mis":"M3-1-u1-X07"},{"t":"305","mis":"M3-1-u1-X14"},{"t":"415","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 3에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 8 = 5.","십의 자리: 1 줄어든 4 − 3 = 1.","백의 자리: 4 − 1 = 3 — 그래서 453 − 138 = 315예요."],"variant_rule":{"alt":[{"stem":"765 − 147은 얼마인가요?","options":[{"t":"618","correct":true},{"t":"622","mis":"M3-1-u1-X07"},{"t":"628","mis":"M3-1-u1-X08"},{"t":"608","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 15 − 7 = 8.","십의 자리: 1 줄어든 5 − 4 = 1.","백의 자리: 7 − 1 = 6 — 그래서 765 − 147 = 618이에요."]},{"stem":"592 − 203은 얼마인가요?","options":[{"t":"389","correct":true},{"t":"391","mis":"M3-1-u1-X07"},{"t":"399","mis":"M3-1-u1-X08"},{"t":"379","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2에서 3을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 3 = 9.","십의 자리: 1 줄어든 8 − 0 = 8.","백의 자리: 5 − 2 = 3 — 그래서 592 − 203 = 389예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#2','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C6',1,'mc','auto','850 − 431은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"850 − 431은 얼마인가요?","options":[{"t":"419","correct":true},{"t":"421","mis":"M3-1-u1-X07"},{"t":"429","mis":"M3-1-u1-X08"},{"t":"409","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0에서 1을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 1 = 9.","십의 자리: 1 줄어든 4 − 3 = 1.","백의 자리: 8 − 4 = 4 — 그래서 850 − 431 = 419예요."],"variant_rule":{"alt":[{"stem":"715 − 544는 얼마인가요?","options":[{"t":"171","correct":true},{"t":"231","mis":"M3-1-u1-X07"},{"t":"271","mis":"M3-1-u1-X08"},{"t":"181","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 − 4 = 1.","십의 자리: 1에서 4를 뺄 수 없어 백의 자리에서 빌려요 — 11 − 4 = 7.","백의 자리: 1 줄어든 6 − 5 = 1 — 그래서 715 − 544 = 171이에요."]},{"stem":"658 − 382는 얼마인가요?","options":[{"t":"276","correct":true},{"t":"336","mis":"M3-1-u1-X07"},{"t":"376","mis":"M3-1-u1-X08"},{"t":"286","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 − 2 = 6.","십의 자리: 5에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 15 − 8 = 7.","백의 자리: 1 줄어든 5 − 3 = 2 — 그래서 658 − 382 = 276이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#3','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C6',1,'sa','auto','371 − 245를 세로셈으로 계산해요. 일의 자리 1에서 5를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 5를 빼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u1-C6","difficulty":1,"kind":"sa","stem":"371 − 245를 세로셈으로 계산해요. 일의 자리 1에서 5를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 5를 빼나요? 숫자로 쓰세요.","answer":["11"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 1 + 10 = 11이 돼요.","11 − 5 = 6, 십의 자리는 1 줄어요."],"variant_rule":{"alt":[{"stem":"980 − 137을 세로셈으로 계산해요. 일의 자리 0에서 7을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 7을 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 7 = 3, 십의 자리는 1 줄어요."]},{"stem":"780 − 234를 세로셈으로 계산해요. 일의 자리 0에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 4 = 6, 십의 자리는 1 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#4','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C3',1,'mc','auto','483 − 256을 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":4,"concept":"M3-1-u1-C3","difficulty":1,"kind":"mc","stem":"483 − 256을 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 100","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X14"}],"explanation":["483은 약 500, 256은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","500 − 300 = 200 — 약 200이에요. 실제 차 227과 비슷해요."],"variant_rule":{"alt":[{"stem":"280 − 167을 어림하면 약 얼마인가요?","options":[{"t":"약 100","correct":true},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X14"},{"t":"약 500","mis":"M3-1-u1-X12"}],"explanation":["280은 약 300, 167은 약 200으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","300 − 200 = 100 — 약 100이에요. 실제 차 113과 비슷해요."]},{"stem":"662 − 480을 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 100","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X14"}],"explanation":["662는 약 700, 480은 약 500으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","700 − 500 = 200 — 약 200이에요. 실제 차 182와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#5','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C6',2,'mc','auto','사탕이 346개 있었어요. 친구들에게 128개를 나눠 주었어요. 남은 사탕은 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":5,"concept":"M3-1-u1-C6","difficulty":2,"kind":"mc","stem":"사탕이 346개 있었어요. 친구들에게 128개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"218개","correct":true},{"t":"474개","mis":"M3-1-u1-X12"},{"t":"222개","mis":"M3-1-u1-X07"},{"t":"228개","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 346 − 128.","일의 자리: 6에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 16 − 8 = 8.","346 − 128 = 218 — 218개예요."],"variant_rule":{"alt":[{"stem":"사탕이 782개 있었어요. 친구들에게 519개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"263개","correct":true},{"t":"1301개","mis":"M3-1-u1-X12"},{"t":"277개","mis":"M3-1-u1-X07"},{"t":"273개","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 782 − 519.","일의 자리: 2에서 9를 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 9 = 3.","782 − 519 = 263 — 263개예요."]},{"stem":"사탕이 450개 있었어요. 친구들에게 333개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"117개","correct":true},{"t":"783개","mis":"M3-1-u1-X12"},{"t":"123개","mis":"M3-1-u1-X07"},{"t":"127개","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 450 − 333.","일의 자리: 0에서 3을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 3 = 7.","450 − 333 = 117 — 117개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_basic#6','math',3,1,'u1','L06','g3_1_math_u1_L06_basic','lesson_basic','M3-1-u1-C6',2,'ox','auto','582 − 147 = 445예요.',ARRAY['M3-1-u1-X08']::text[],true,'{"seq":6,"concept":"M3-1-u1-C6","difficulty":2,"kind":"ox","stem":"582 − 147 = 445예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 435가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"mis":"M3-1-u1-X08","explanation":["일의 자리: 2에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 7 = 5.","십의 자리: 1 줄어든 7 − 4 = 3.","바른 답은 435예요. 445는 빌려준 자리를 줄이지 않은 값이에요."],"variant_rule":{"alt":[{"stem":"494 − 135 = 369예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 359가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 4에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 5 = 9.","십의 자리: 1 줄어든 8 − 3 = 5.","바른 답은 359예요. 369는 빌려준 자리를 줄이지 않은 값이에요."]},{"stem":"780 − 242 = 548이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 538이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 0에서 2를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 2 = 8.","십의 자리: 1 줄어든 7 − 4 = 3.","바른 답은 538이에요. 548은 빌려준 자리를 줄이지 않은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
