INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#1','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C6',2,'mc','auto','490 − 366은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C6","difficulty":2,"kind":"mc","stem":"490 − 366은 얼마인가요?","options":[{"t":"124","correct":true},{"t":"136","mis":"M3-1-u1-X07"},{"t":"134","mis":"M3-1-u1-X08"},{"t":"114","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 6 = 4.","십의 자리: 1 줄어든 8 − 6 = 2.","백의 자리: 4 − 3 = 1 — 그래서 490 − 366 = 124예요."],"variant_rule":{"alt":[{"stem":"651 − 526은 얼마인가요?","options":[{"t":"125","correct":true},{"t":"135","mis":"M3-1-u1-X07"},{"t":"115","mis":"M3-1-u1-X14"},{"t":"225","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 6 = 5.","십의 자리: 1 줄어든 4 − 2 = 2.","백의 자리: 6 − 5 = 1 — 그래서 651 − 526 = 125예요."]},{"stem":"667 − 473은 얼마인가요?","options":[{"t":"194","correct":true},{"t":"214","mis":"M3-1-u1-X07"},{"t":"294","mis":"M3-1-u1-X08"},{"t":"204","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 − 3 = 4.","십의 자리: 6에서 7을 뺄 수 없어 백의 자리에서 빌려요 — 16 − 7 = 9.","백의 자리: 1 줄어든 5 − 4 = 1 — 그래서 667 − 473 = 194예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#2','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C3',2,'mc','auto','849 − 554를 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"849 − 554를 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 100","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X14"}],"explanation":["849는 약 800, 554는 약 600으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","800 − 600 = 200 — 약 200이에요. 실제 차 295와 비슷해요."],"variant_rule":{"alt":[{"stem":"411 − 141을 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X14"}],"explanation":["411은 약 400, 141은 약 100으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","400 − 100 = 300 — 약 300이에요. 실제 차 270과 비슷해요."]},{"stem":"946 − 327을 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X14"}],"explanation":["946은 약 900, 327은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","900 − 300 = 600 — 약 600이에요. 실제 차 619와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#3','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C6',3,'error','auto','453 − 138을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X08','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C6","difficulty":3,"kind":"error","stem":"453 − 138을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도영 — 「일의 자리에서 13 − 8 = 5를 하고, 십의 자리는 5 − 3 = 2라서 325야.」","correct":true,"mis_target":"M3-1-u1-X08"},{"t":"나린 — 「십에서 빌려 왔으니 십의 자리는 4 − 3 = 1이야.」","mis":"M3-1-u1-X15"},{"t":"하람 — 「받아내림을 표시하면 315야.」","mis":"M3-1-u1-X15"}],"explanation":["일의 자리는 십에서 10을 빌려 13 − 8 = 5예요.","빌려준 십의 자리는 5에서 4로 줄어 4 − 3 = 1이에요.","도영이는 빌려준 자리를 줄이지 않았어요. 바른 답은 315예요."],"variant_rule":{"alt":[{"stem":"582 − 147을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도영 — 「일의 자리에서 12 − 7 = 5를 하고, 십의 자리는 8 − 4 = 4라서 445야.」","correct":true,"mis_target":"M3-1-u1-X08"},{"t":"나린 — 「십에서 빌려 왔으니 십의 자리는 7 − 4 = 3이야.」","mis":"M3-1-u1-X15"},{"t":"하람 — 「받아내림을 표시하면 435야.」","mis":"M3-1-u1-X15"}],"explanation":["일은 12 − 7 = 5.","빌려준 십은 7 − 4 = 3.","도영이는 빌려준 자리를 줄이지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
