INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#8','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C6',4,'essay','teacher','453 − 138을 수 모형으로 계산하는 과정을 설명하고, 받아내림한 뒤 십의 자리 계산에서 조심할 점을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C6","difficulty":4,"kind":"essay","stem":"453 − 138을 수 모형으로 계산하는 과정을 설명하고, 받아내림한 뒤 십의 자리 계산에서 조심할 점을 써 보세요.","answer_guide":{"answer":"예: 453에서 일 모형 3개로는 8개를 덜어 낼 수 없어 십 모형 1개를 일 모형 10개로 바꾼다. 13 − 8 = 5. 십 모형은 5개에서 4개로 줄었으므로 4 − 3 = 1, 백은 4 − 1 = 3이라 315이다. 빌려준 십의 자리를 1 줄여야 한다.","scoring_points":["십 모형 1개를 일 모형 10개로 바꾼다고 썼는가","빌려준 십의 자리를 1 줄인다고 썼는가","315를 구했는가"]},"explanation":["십 모형 1개 = 일 모형 10개 — 13 − 8 = 5.","십의 자리는 4 − 3 = 1.","453 − 138 = 315예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#9','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C3',4,'essay','teacher','댓글 453개 가운데 138개를 지웠어요. 남은 댓글 수를 어림하고, 실제로 계산한 값과 견주어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C3","difficulty":4,"kind":"essay","stem":"댓글 453개 가운데 138개를 지웠어요. 남은 댓글 수를 어림하고, 실제로 계산한 값과 견주어 보세요.","answer_guide":{"answer":"예: 453은 약 450, 138은 약 140이라 남은 댓글은 약 310개로 어림할 수 있다. 실제로 계산하면 453 − 138 = 315개로 어림한 310과 비슷하니 계산이 맞다.","scoring_points":["두 수를 어림했는가","어림한 차를 구했는가","315와 견주어 비슷하다고 썼는가"]},"explanation":["453은 약 450, 138은 약 140이에요.","어림한 차는 약 310이에요.","계산한 315와 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L06_challenge#10','math',3,1,'u1','L06','g3_1_math_u1_L06_challenge','lesson_challenge','M3-1-u1-C6',4,'mc','auto','OX 퀴즈에서 O를 821명, X를 480명이 골랐어요. O를 고른 사람은 X보다 몇 명 더 많은가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":10,"concept":"M3-1-u1-C6","difficulty":4,"kind":"mc","stem":"OX 퀴즈에서 O를 821명, X를 480명이 골랐어요. O를 고른 사람은 X보다 몇 명 더 많은가요?","options":[{"t":"341명","correct":true},{"t":"1301명","mis":"M3-1-u1-X12"},{"t":"461명","mis":"M3-1-u1-X07"},{"t":"441명","mis":"M3-1-u1-X08"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 821 − 480.","일의 자리: 1 − 0 = 1.","821 − 480 = 341 — 341명이에요."],"variant_rule":{"alt":[{"stem":"OX 퀴즈에서 O를 908명, X를 127명이 골랐어요. O를 고른 사람은 X보다 몇 명 더 많은가요?","options":[{"t":"781명","correct":true},{"t":"1035명","mis":"M3-1-u1-X12"},{"t":"821명","mis":"M3-1-u1-X07"},{"t":"881명","mis":"M3-1-u1-X08"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 908 − 127.","일의 자리: 8 − 7 = 1.","908 − 127 = 781 — 781명이에요."]},{"stem":"OX 퀴즈에서 O를 533명, X를 360명이 골랐어요. O를 고른 사람은 X보다 몇 명 더 많은가요?","options":[{"t":"173명","correct":true},{"t":"893명","mis":"M3-1-u1-X12"},{"t":"233명","mis":"M3-1-u1-X07"},{"t":"273명","mis":"M3-1-u1-X08"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 533 − 360.","일의 자리: 3 − 0 = 3.","533 − 360 = 173 — 173명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
