INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_basic#4','math',3,1,'u1','L07','g3_1_math_u1_L07_basic','lesson_basic','M3-1-u1-C7',1,'sa','auto','340 − 256은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C7","difficulty":1,"kind":"sa","stem":"340 − 256은 얼마인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["일의 자리: 0에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 6 = 4.","십의 자리: 1 줄어든 3에서 5를 뺄 수 없어 백의 자리에서 빌려요 — 13 − 5 = 8.","백의 자리는 2 − 2 = 0이라 쓰지 않아요 — 그래서 340 − 256 = 84예요."],"variant_rule":{"alt":[{"stem":"623 − 526은 얼마인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["일의 자리: 3에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 6 = 7.","십의 자리: 1 줄어든 1에서 2를 뺄 수 없어 백의 자리에서 빌려요 — 11 − 2 = 9.","백의 자리는 5 − 5 = 0이라 쓰지 않아요 — 그래서 623 − 526 = 97이에요."]},{"stem":"650 − 589는 얼마인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["일의 자리: 0에서 9를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 9 = 1.","십의 자리: 1 줄어든 4에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 14 − 8 = 6.","백의 자리는 5 − 5 = 0이라 쓰지 않아요 — 그래서 650 − 589 = 61이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_basic#5','math',3,1,'u1','L07','g3_1_math_u1_L07_basic','lesson_basic','M3-1-u1-C7',2,'mc','auto','도서관에 책이 712권 있었어요. 그중 358권을 빌려 갔어요. 남은 책은 몇 권인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":5,"concept":"M3-1-u1-C7","difficulty":2,"kind":"mc","stem":"도서관에 책이 712권 있었어요. 그중 358권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"354권","correct":true},{"t":"1070권","mis":"M3-1-u1-X12"},{"t":"446권","mis":"M3-1-u1-X07"},{"t":"364권","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 712 − 358.","일의 자리: 2에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 8 = 4.","712 − 358 = 354 — 354권이에요."],"variant_rule":{"alt":[{"stem":"도서관에 책이 722권 있었어요. 그중 494권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"228권","correct":true},{"t":"1216권","mis":"M3-1-u1-X12"},{"t":"372권","mis":"M3-1-u1-X07"},{"t":"238권","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 722 − 494.","일의 자리: 2에서 4를 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 4 = 8.","722 − 494 = 228 — 228권이에요."]},{"stem":"도서관에 책이 562권 있었어요. 그중 384권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"178권","correct":true},{"t":"946권","mis":"M3-1-u1-X12"},{"t":"222권","mis":"M3-1-u1-X07"},{"t":"188권","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 562 − 384.","일의 자리: 2에서 4를 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 4 = 8.","562 − 384 = 178 — 178권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_basic#6','math',3,1,'u1','L07','g3_1_math_u1_L07_basic','lesson_basic','M3-1-u1-C3',2,'mc','auto','614 − 258을 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":6,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"614 − 258을 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X14"}],"explanation":["614는 약 600, 258은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","600 − 300 = 300 — 약 300이에요. 실제 차 356과 비슷해요."],"variant_rule":{"alt":[{"stem":"921 − 638을 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X14"}],"explanation":["921은 약 900, 638은 약 600으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","900 − 600 = 300 — 약 300이에요. 실제 차 283과 비슷해요."]},{"stem":"942 − 196을 어림하면 약 얼마인가요?","options":[{"t":"약 700","correct":true},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X14"}],"explanation":["942는 약 900, 196은 약 200으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","900 − 200 = 700 — 약 700이에요. 실제 차 746과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_basic#7','math',3,1,'u1','L07','g3_1_math_u1_L07_basic','lesson_basic','M3-1-u1-C7',2,'ox','auto','703 − 485에서 일의 자리는 십의 자리에서 빌려 오면 되는데, 십의 자리가 0이라 백의 자리에서 먼저 빌려 와야 해요.',ARRAY['M3-1-u1-X09']::text[],false,'{"seq":7,"concept":"M3-1-u1-C7","difficulty":2,"kind":"ox","stem":"703 − 485에서 일의 자리는 십의 자리에서 빌려 오면 되는데, 십의 자리가 0이라 백의 자리에서 먼저 빌려 와야 해요.","answer":"O","reason_options":[{"t":"0에서는 빌려줄 수 없어 백에서 빌린 100을 십의 자리 90과 일의 자리 10으로 나누어서","correct":true},{"t":"십의 자리가 0이면 일의 자리를 그냥 0으로 두면 되어서","mis":"M3-1-u1-X09"}],"mis":"M3-1-u1-X09","explanation":["십의 자리가 0이면 빌려줄 십 모형이 없어요.","백 모형 1개를 십 모형 10개로 바꾸고, 그중 1개를 일 모형 10개로 바꿔요.","그래서 백 6, 십 9, 일 13이 돼요 — 703 − 485 = 218."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_basic#8','math',3,1,'u1','L07','g3_1_math_u1_L07_basic','lesson_basic','M3-1-u1-C7',2,'match','auto','뺄셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u1-C7","difficulty":2,"kind":"match","stem":"뺄셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"812 − 197","r":"615"},{"l":"921 − 495","r":"426"},{"l":"412 − 114","r":"298"}],"mis":"M3-1-u1-X08","explanation":["같은 자리끼리 일 → 십 → 백 차례로 빼요.","뺄 수 없으면 윗자리에서 빌리고 그 자리는 1 줄여요.","812 − 197 = 615, 921 − 495 = 426, 412 − 114 = 298이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 뺄셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"522 − 236","r":"286"},{"l":"530 − 298","r":"232"},{"l":"915 − 118","r":"797"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 빼요.","뺄 수 없으면 윗자리에서 빌리고 그 자리는 1 줄여요.","522 − 236 = 286, 530 − 298 = 232, 915 − 118 = 797이에요."]},{"stem":"이번에는 다른 수예요. 뺄셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"376 − 187","r":"189"},{"l":"430 − 249","r":"181"},{"l":"432 − 196","r":"236"}],"explanation":["같은 자리끼리 일 → 십 → 백 차례로 빼요.","뺄 수 없으면 윗자리에서 빌리고 그 자리는 1 줄여요.","376 − 187 = 189, 430 − 249 = 181, 432 − 196 = 236이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
