INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#1','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',2,'mc','auto','705 − 208은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X09','M3-1-u1-X10']::text[],true,'{"seq":1,"concept":"M3-1-u1-C7","difficulty":2,"kind":"mc","stem":"705 − 208은 얼마인가요?","options":[{"t":"497","correct":true},{"t":"503","mis":"M3-1-u1-X07"},{"t":"507","mis":"M3-1-u1-X09"},{"t":"597","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 5에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 15 − 8 = 7.","십의 자리가 0이라 백의 자리에서 빌려 십의 자리를 9로 만들어요 — 9 − 0 = 9.","백의 자리: 1 줄어든 6 − 2 = 4 — 그래서 705 − 208 = 497이에요."],"variant_rule":{"alt":[{"stem":"600 − 276은 얼마인가요?","options":[{"t":"324","correct":true},{"t":"476","mis":"M3-1-u1-X07"},{"t":"334","mis":"M3-1-u1-X09"},{"t":"424","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 0에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 6 = 4.","십의 자리가 0이라 백의 자리에서 빌려 십의 자리를 9로 만들어요 — 9 − 7 = 2.","백의 자리: 1 줄어든 5 − 2 = 3 — 그래서 600 − 276 = 324예요."]},{"stem":"504 − 217은 얼마인가요?","options":[{"t":"287","correct":true},{"t":"313","mis":"M3-1-u1-X07"},{"t":"297","mis":"M3-1-u1-X09"},{"t":"387","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 4에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 7 = 7.","십의 자리가 0이라 백의 자리에서 빌려 십의 자리를 9로 만들어요 — 9 − 1 = 8.","백의 자리: 1 줄어든 4 − 2 = 2 — 그래서 504 − 217 = 287이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#2','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',2,'sa','auto','244 − 145는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u1-C7","difficulty":2,"kind":"sa","stem":"244 − 145는 얼마인가요? 숫자로 쓰세요.","answer":["99"],"explanation":["일의 자리: 4에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 5 = 9.","십의 자리: 1 줄어든 3에서 4를 뺄 수 없어 백의 자리에서 빌려요 — 13 − 4 = 9.","백의 자리는 1 − 1 = 0이라 쓰지 않아요 — 그래서 244 − 145 = 99예요."],"variant_rule":{"alt":[{"stem":"333 − 265는 얼마인가요? 숫자로 쓰세요.","answer":["68"],"explanation":["일의 자리: 3에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 5 = 8.","십의 자리: 1 줄어든 2에서 6을 뺄 수 없어 백의 자리에서 빌려요 — 12 − 6 = 6.","백의 자리는 2 − 2 = 0이라 쓰지 않아요 — 그래서 333 − 265 = 68이에요."]},{"stem":"705 − 626은 얼마인가요? 숫자로 쓰세요.","answer":["79"],"explanation":["일의 자리: 5에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 15 − 6 = 9.","십의 자리가 0이라 백의 자리에서 빌려 십의 자리를 9로 만들어요 — 9 − 2 = 7.","백의 자리는 6 − 6 = 0이라 쓰지 않아요 — 그래서 705 − 626 = 79예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#3','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',3,'error','auto','703 − 485를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M3-1-u1-X09','M3-1-u1-X15']::text[],true,'{"seq":3,"concept":"M3-1-u1-C7","difficulty":3,"kind":"error","stem":"703 − 485를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"유나 — 「백에서 빌려 십의 자리를 10으로 두고 일의 자리 13 − 5 = 8, 십의 자리 10 − 8 = 2라서 228이야.」","correct":true,"mis_target":"M3-1-u1-X09"},{"t":"지호 — 「백에서 빌린 100을 90과 10으로 나눠서 십은 9, 일은 13이 돼.」","mis":"M3-1-u1-X15"},{"t":"민서 — 「일 13 − 5 = 8, 십 9 − 8 = 1, 백 6 − 4 = 2라서 218이야.」","mis":"M3-1-u1-X15"}],"explanation":["십의 자리가 0이라 백에서 빌려 십 9개 + 일 10개로 나눠요.","일 13 − 5 = 8, 십 9 − 8 = 1, 백 6 − 4 = 2예요.","유나는 일의 자리로 10을 빌려준 뒤에도 십의 자리를 10으로 두었어요. 바른 답은 218이에요."],"variant_rule":{"alt":[{"stem":"604 − 357을 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"유나 — 「백에서 빌려 십의 자리를 10으로 두고 일의 자리 14 − 7 = 7, 십의 자리 10 − 5 = 5라서 257이야.」","correct":true,"mis_target":"M3-1-u1-X09"},{"t":"지호 — 「백에서 빌린 100을 90과 10으로 나눠서 십은 9, 일은 14가 돼.」","mis":"M3-1-u1-X15"},{"t":"민서 — 「일 14 − 7 = 7, 십 9 − 5 = 4, 백 5 − 3 = 2라서 247이야.」","mis":"M3-1-u1-X15"}],"explanation":["십의 자리 0 — 백에서 빌려 9와 10으로.","일 7, 십 4, 백 2 — 247이에요.","유나는 십의 자리를 9로 줄이지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#4','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',3,'mc','auto','드론이 760대 있었어요. 그중 175대가 날아갔어요. 남은 드론은 몇 대인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":4,"concept":"M3-1-u1-C7","difficulty":3,"kind":"mc","stem":"드론이 760대 있었어요. 그중 175대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"585대","correct":true},{"t":"935대","mis":"M3-1-u1-X12"},{"t":"615대","mis":"M3-1-u1-X07"},{"t":"595대","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 760 − 175.","일의 자리: 0에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 5 = 5.","760 − 175 = 585 — 585대예요."],"variant_rule":{"alt":[{"stem":"드론이 740대 있었어요. 그중 392대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"348대","correct":true},{"t":"1132대","mis":"M3-1-u1-X12"},{"t":"452대","mis":"M3-1-u1-X07"},{"t":"358대","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 740 − 392.","일의 자리: 0에서 2를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 2 = 8.","740 − 392 = 348 — 348대예요."]},{"stem":"드론이 724대 있었어요. 그중 385대가 날아갔어요. 남은 드론은 몇 대인가요?","options":[{"t":"339대","correct":true},{"t":"1109대","mis":"M3-1-u1-X12"},{"t":"461대","mis":"M3-1-u1-X07"},{"t":"349대","mis":"M3-1-u1-X08"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 724 − 385.","일의 자리: 4에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 5 = 9.","724 − 385 = 339 — 339대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#5','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',3,'ox','auto','824 − 226 = 608이에요.',ARRAY['M3-1-u1-X08']::text[],true,'{"seq":5,"concept":"M3-1-u1-C7","difficulty":3,"kind":"ox","stem":"824 − 226 = 608이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 598이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"mis":"M3-1-u1-X08","explanation":["일의 자리: 4에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 6 = 8.","십의 자리: 1 줄어든 1에서 2를 뺄 수 없어 백의 자리에서 빌려요 — 11 − 2 = 9.","바른 답은 598이에요. 608은 빌려준 자리를 줄이지 않은 값이에요."],"variant_rule":{"alt":[{"stem":"841 − 287 = 564예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 554가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 1에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 7 = 4.","십의 자리: 1 줄어든 3에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 13 − 8 = 5.","바른 답은 554예요. 564는 빌려준 자리를 줄이지 않은 값이에요."]},{"stem":"742 − 286 = 466이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 456이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 2에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 6 = 6.","십의 자리: 1 줄어든 3에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 13 − 8 = 5.","바른 답은 456이에요. 466은 빌려준 자리를 줄이지 않은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#6','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',3,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X15']::text[],true,'{"seq":6,"concept":"M3-1-u1-C7","difficulty":3,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"700 − 193 = 693","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"981 − 285 = 696","mis":"M3-1-u1-X15"},{"t":"621 − 229 = 392","mis":"M3-1-u1-X15"},{"t":"823 − 146 = 677","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","700 − 193은 받아내림을 하면 507이에요.","693은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"802 − 537 = 335","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"836 − 688 = 148","mis":"M3-1-u1-X15"},{"t":"582 − 287 = 295","mis":"M3-1-u1-X15"},{"t":"438 − 249 = 189","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","802 − 537은 받아내림을 하면 265예요.","335는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"806 − 309 = 503","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"713 − 166 = 547","mis":"M3-1-u1-X15"},{"t":"531 − 384 = 147","mis":"M3-1-u1-X15"},{"t":"331 − 143 = 188","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","806 − 309는 받아내림을 하면 497이에요.","503은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#7','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',3,'mc','auto','두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 263 + 238 ○ 964 − 365',ARRAY['M3-1-u1-X13','M3-1-u1-X14','M3-1-u1-X15']::text[],true,'{"seq":7,"concept":"M3-1-u1-C7","difficulty":3,"kind":"mc","stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 263 + 238 ○ 964 − 365","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 263 + 238 = 501.","오른쪽: 964 − 365 = 599.","501 < 599 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 119 + 785 ○ 972 − 157","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 119 + 785 = 904.","오른쪽: 972 − 157 = 815.","904 > 815 — 알맞은 것은 >예요."]},{"stem":"두 식의 값을 견주어 ○ 안에 알맞은 것을 고르세요. 338 + 176 ○ 916 − 349","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u1-X13"},{"t":"=","mis":"M3-1-u1-X14"},{"t":"알 수 없다","mis":"M3-1-u1-X15"}],"explanation":["왼쪽: 338 + 176 = 514.","오른쪽: 916 − 349 = 567.","514 < 567 — 알맞은 것은 <예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#8','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',4,'essay','teacher','621 − 147을 계산하는 과정을 일 → 십 → 백의 자리 차례로 쓰고, 받아내림이 몇 번 일어나는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C7","difficulty":4,"kind":"essay","stem":"621 − 147을 계산하는 과정을 일 → 십 → 백의 자리 차례로 쓰고, 받아내림이 몇 번 일어나는지 설명해 보세요.","answer_guide":{"answer":"예: 일 1에서 7을 뺄 수 없어 십에서 빌려 11 − 7 = 4, 십은 2에서 1로 줄어든다. 십 1에서 4를 뺄 수 없어 백에서 빌려 11 − 4 = 7, 백은 6에서 5로 줄어든다. 백 5 − 1 = 4. 그래서 474이고 받아내림은 두 번이다.","scoring_points":["일·십·백 차례로 계산했는가","받아내림 두 번과 줄어든 자리를 밝혔는가","474를 구했는가"]},"explanation":["일 11 − 7 = 4, 십은 1로 줄어요.","십 11 − 4 = 7, 백은 5로 줄어요.","백 5 − 1 = 4 — 474, 받아내림 두 번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#9','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',4,'essay','teacher','340 − 256처럼 0이 있는 수의 뺄셈에서 받아내림을 어떻게 하는지 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C7","difficulty":4,"kind":"essay","stem":"340 − 256처럼 0이 있는 수의 뺄셈에서 받아내림을 어떻게 하는지 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 일의 자리 0에서 6을 뺄 수 없어 십에서 빌려 10 − 6 = 4, 십은 4에서 3으로 줄어든다. 십 3에서 5를 뺄 수 없어 백에서 빌려 13 − 5 = 8, 백은 3에서 2로 줄어 2 − 2 = 0이다. 그래서 84이다.","scoring_points":["일의 자리 받아내림을 설명했는가","십의 자리 받아내림과 줄어든 백의 자리를 설명했는가","84를 구했는가"]},"explanation":["일 10 − 6 = 4.","십 13 − 5 = 8, 백 2 − 2 = 0.","340 − 256 = 84예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L07_challenge#10','math',3,1,'u1','L07','g3_1_math_u1_L07_challenge','lesson_challenge','M3-1-u1-C7',4,'sa','auto','301 − 238은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u1-C7","difficulty":4,"kind":"sa","stem":"301 − 238은 얼마인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["일의 자리: 1에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 8 = 3.","십의 자리가 0이라 백의 자리에서 빌려 십의 자리를 9로 만들어요 — 9 − 3 = 6.","백의 자리는 2 − 2 = 0이라 쓰지 않아요 — 그래서 301 − 238 = 63이에요."],"variant_rule":{"alt":[{"stem":"245 − 178은 얼마인가요? 숫자로 쓰세요.","answer":["67"],"explanation":["일의 자리: 5에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 15 − 8 = 7.","십의 자리: 1 줄어든 3에서 7을 뺄 수 없어 백의 자리에서 빌려요 — 13 − 7 = 6.","백의 자리는 1 − 1 = 0이라 쓰지 않아요 — 그래서 245 − 178 = 67이에요."]},{"stem":"511 − 456은 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["일의 자리: 1에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 6 = 5.","십의 자리: 1 줄어든 0에서 5를 뺄 수 없어 백의 자리에서 빌려요 — 10 − 5 = 5.","백의 자리는 4 − 4 = 0이라 쓰지 않아요 — 그래서 511 − 456 = 55예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_basic#1','math',3,1,'u1','L08','g3_1_math_u1_L08_basic','lesson_basic','M3-1-u1-C8',1,'mc','auto','비사치기에서 발등으로 234점, 배로 359점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":1,"concept":"M3-1-u1-C8","difficulty":1,"kind":"mc","stem":"비사치기에서 발등으로 234점, 배로 359점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"593점","correct":true},{"t":"583점","mis":"M3-1-u1-X02"},{"t":"683점","mis":"M3-1-u1-X03"},{"t":"5813점","mis":"M3-1-u1-X04"}],"explanation":["모은 점수는 덧셈 — 234 + 359.","십의 자리: 3 + 5 + 1 = 9.","234 + 359 = 593점이에요."],"variant_rule":{"alt":[{"stem":"비사치기에서 손등으로 318점, 무릎으로 276점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"594점","correct":true},{"t":"584점","mis":"M3-1-u1-X02"},{"t":"684점","mis":"M3-1-u1-X03"},{"t":"5814점","mis":"M3-1-u1-X04"}],"explanation":["모은 점수는 덧셈 — 318 + 276.","십의 자리: 1 + 7 + 1 = 9.","318 + 276 = 594점이에요."]},{"stem":"비사치기에서 무릎으로 276점, 발등으로 234점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"510점","correct":true},{"t":"400점","mis":"M3-1-u1-X02"},{"t":"410점","mis":"M3-1-u1-X05"},{"t":"520점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 276 + 234.","십의 자리: 7 + 3 + 1 = 11 — 백의 자리로 받아올려요.","276 + 234 = 510점이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
