INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_basic#6','math',3,1,'u1','L08','g3_1_math_u1_L08_basic','lesson_basic','M3-1-u1-C8',2,'mc','auto','배 359점과 손등 318점을 얻었어요. 이 점수로 축구공(755점)을 바꿀 수 있나요?',ARRAY['M3-1-u1-X13','M3-1-u1-X15']::text[],true,'{"seq":6,"concept":"M3-1-u1-C8","difficulty":2,"kind":"mc","stem":"배 359점과 손등 318점을 얻었어요. 이 점수로 축구공(755점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"배 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 359 + 318 = 677.","677점과 축구공 755점을 견주면 677 < 755예요.","그래서 바꿀 수 없어요."],"variant_rule":{"alt":[{"stem":"발등 234점과 무릎 276점을 얻었어요. 이 점수로 줄넘기(543점)를 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"발등 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 234 + 276 = 510.","510점과 줄넘기 543점을 견주면 510 < 543이에요.","그래서 바꿀 수 없어요."]},{"stem":"어깨 465점과 배 359점을 얻었어요. 이 점수로 색연필(685점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"어깨 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 465 + 359 = 824.","824점과 색연필 685점을 견주면 824 > 685예요.","그래서 바꿀 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_basic#7','math',3,1,'u1','L08','g3_1_math_u1_L08_basic','lesson_basic','M3-1-u1-C8',2,'mc','auto','비사치기 점수로 물건을 바꿀 수 있는지 알아보려면 어떻게 해야 하나요?',ARRAY['M3-1-u1-X13','M3-1-u1-X12']::text[],false,'{"seq":7,"concept":"M3-1-u1-C8","difficulty":2,"kind":"mc","stem":"비사치기 점수로 물건을 바꿀 수 있는지 알아보려면 어떻게 해야 하나요?","options":[{"t":"얻은 점수를 모두 더한 뒤 물건 점수와 크기를 견준다","correct":true},{"t":"얻은 점수 가운데 가장 큰 것만 본다","mis":"M3-1-u1-X13"},{"t":"물건 점수에서 얻은 점수를 더한다","mis":"M3-1-u1-X12"},{"t":"점수의 백의 자리 숫자만 더한다","mis":"M3-1-u1-X13"}],"explanation":["먼저 덧셈으로 모은 점수를 구해요.","그다음 물건 점수와 크기를 견주어요.","모은 점수가 같거나 크면 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_basic#8','math',3,1,'u1','L08','g3_1_math_u1_L08_basic','lesson_basic','M3-1-u1-C8',2,'mc','auto','852점으로 보드게임(816점)을 바꿨어요. 남은 점수는 몇 점인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":8,"concept":"M3-1-u1-C8","difficulty":2,"kind":"mc","stem":"852점으로 보드게임(816점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"36점","correct":true},{"t":"1668점","mis":"M3-1-u1-X12"},{"t":"44점","mis":"M3-1-u1-X07"},{"t":"46점","mis":"M3-1-u1-X08"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 852 − 816.","일의 자리: 2에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 6 = 6.","852 − 816 = 36점 남아요."],"variant_rule":{"alt":[{"stem":"746점으로 필통(627점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"119점","correct":true},{"t":"1373점","mis":"M3-1-u1-X12"},{"t":"121점","mis":"M3-1-u1-X07"},{"t":"129점","mis":"M3-1-u1-X08"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 746 − 627.","일의 자리: 6에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 16 − 7 = 9.","746 − 627 = 119점 남아요."]},{"stem":"930점으로 색연필(685점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"245점","correct":true},{"t":"1615점","mis":"M3-1-u1-X12"},{"t":"355점","mis":"M3-1-u1-X07"},{"t":"255점","mis":"M3-1-u1-X08"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 930 − 685.","일의 자리: 0에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 5 = 5.","930 − 685 = 245점 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
