INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_basic#10','math',3,1,'u1','L08','g3_1_math_u1_L08_basic','lesson_basic','M3-1-u1-C8',3,'mc','auto','보드게임(816점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.',ARRAY['M3-1-u1-X13']::text[],true,'{"seq":10,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"보드게임(816점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"어깨 + 머리 (약 1000)","correct":true},{"t":"어깨 + 무릎 (약 800)","mis":"M3-1-u1-X13"},{"t":"발등 + 어깨 (약 700)","mis":"M3-1-u1-X13"},{"t":"머리 + 발등 (약 700)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","어깨 + 머리는 약 1000으로 816점을 넘을 만해요 — 실제로 957점이에요.","다른 짝은 어림한 값부터 816점에 못 미쳐요."],"variant_rule":{"alt":[{"stem":"축구공(755점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"어깨 + 이마 (약 900)","correct":true},{"t":"무릎 + 발등 (약 500)","mis":"M3-1-u1-X13"},{"t":"배 + 손등 (약 700)","mis":"M3-1-u1-X13"},{"t":"배 + 발등 (약 600)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","어깨 + 이마는 약 900으로 755점을 넘을 만해요 — 실제로 852점이에요.","다른 짝은 어림한 값부터 755점에 못 미쳐요."]},{"stem":"색연필(685점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"이마 + 머리 (약 900)","correct":true},{"t":"손등 + 무릎 (약 600)","mis":"M3-1-u1-X13"},{"t":"배 + 무릎 (약 700)","mis":"M3-1-u1-X13"},{"t":"발등 + 이마 (약 600)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","이마 + 머리는 약 900으로 685점을 넘을 만해요 — 실제로 879점이에요.","다른 짝은 어림한 값부터 685점에 못 미쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
