INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#2','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',2,'sa','auto','683점으로 필통(627점)을 바꿨어요. 남은 점수는 몇 점인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u1-C8","difficulty":2,"kind":"sa","stem":"683점으로 필통(627점)을 바꿨어요. 남은 점수는 몇 점인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["바꾸고 남은 점수는 뺄셈 — 683 − 627.","일의 자리: 3에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 7 = 6.","683 − 627 = 56점 남아요."],"variant_rule":{"alt":[{"stem":"750점으로 퍼즐(708점)을 바꿨어요. 남은 점수는 몇 점인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["바꾸고 남은 점수는 뺄셈 — 750 − 708.","일의 자리: 0에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 8 = 2.","750 − 708 = 42점 남아요."]},{"stem":"771점으로 축구공(755점)을 바꿨어요. 남은 점수는 몇 점인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["바꾸고 남은 점수는 뺄셈 — 771 − 755.","일의 자리: 1에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 5 = 6.","771 − 755 = 16점 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#3','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',3,'error','auto','어깨 465점과 이마 387점을 얻은 뒤 보드게임(816점)을 바꿀 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u1-X13','M3-1-u1-X15']::text[],false,'{"seq":3,"concept":"M3-1-u1-C8","difficulty":3,"kind":"error","stem":"어깨 465점과 이마 387점을 얻은 뒤 보드게임(816점)을 바꿀 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「465점이 816점보다 작으니까 바꿀 수 없어.」","correct":true,"mis_target":"M3-1-u1-X13"},{"t":"지안 — 「465 + 387 = 852점이라 바꿀 수 있어.」","mis":"M3-1-u1-X15"},{"t":"하은 — 「바꾸고 나면 852 − 816 = 36점이 남아.」","mis":"M3-1-u1-X15"}],"explanation":["두 점수를 모두 더해야 해요 — 465 + 387 = 852.","852 > 816이라 바꿀 수 있어요.","현우는 한 점수만 보고 판단했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#4','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',3,'mc','auto','보드게임(816점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.',ARRAY['M3-1-u1-X13']::text[],true,'{"seq":4,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"보드게임(816점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"머리 + 배 (약 900)","correct":true},{"t":"무릎 + 발등 (약 500)","mis":"M3-1-u1-X13"},{"t":"배 + 발등 (약 600)","mis":"M3-1-u1-X13"},{"t":"발등 + 이마 (약 600)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","머리 + 배는 약 900으로 816점을 넘을 만해요 — 실제로 851점이에요.","다른 짝은 어림한 값부터 816점에 못 미쳐요."],"variant_rule":{"alt":[{"stem":"퍼즐(708점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"이마 + 배 (약 800)","correct":true},{"t":"배 + 무릎 (약 700)","mis":"M3-1-u1-X13"},{"t":"발등 + 무릎 (약 500)","mis":"M3-1-u1-X13"},{"t":"발등 + 이마 (약 600)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","이마 + 배는 약 800으로 708점을 넘을 만해요 — 실제로 746점이에요.","다른 짝은 어림한 값부터 708점에 못 미쳐요."]},{"stem":"축구공(755점)을 바꾸려고 해요. 어떤 두 방법의 점수를 모으면 될까요? 어림해서 고르세요.","options":[{"t":"손등 + 머리 (약 800)","correct":true},{"t":"손등 + 이마 (약 700)","mis":"M3-1-u1-X13"},{"t":"어깨 + 발등 (약 700)","mis":"M3-1-u1-X13"},{"t":"배 + 손등 (약 700)","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 가까운 몇백으로 어림해 더해요.","손등 + 머리는 약 800으로 755점을 넘을 만해요 — 실제로 810점이에요.","다른 짝은 어림한 값부터 755점에 못 미쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#5','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',3,'mc','auto','발등 234점과 손등 318점을 얻었어요. 이 점수로 필통(627점)을 바꿀 수 있나요?',ARRAY['M3-1-u1-X13','M3-1-u1-X15']::text[],true,'{"seq":5,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"발등 234점과 손등 318점을 얻었어요. 이 점수로 필통(627점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"발등 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 234 + 318 = 552.","552점과 필통 627점을 견주면 552 < 627이에요.","그래서 바꿀 수 없어요."],"variant_rule":{"alt":[{"stem":"무릎 276점과 배 359점을 얻었어요. 이 점수로 축구공(755점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"무릎 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 276 + 359 = 635.","635점과 축구공 755점을 견주면 635 < 755예요.","그래서 바꿀 수 없어요."]},{"stem":"발등 234점과 머리 492점을 얻었어요. 이 점수로 필통(627점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"발등 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 234 + 492 = 726.","726점과 필통 627점을 견주면 726 > 627이에요.","그래서 바꿀 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#6','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',3,'mc','auto','어깨 465점과 이마 387점으로 보드게임(816점)을 바꾸고, 남은 점수로 무엇을 더 할 수 있나요? 남은 점수를 구하는 식으로 알맞은 것을 고르세요.',ARRAY['M3-1-u1-X12','M3-1-u1-X01']::text[],false,'{"seq":6,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"어깨 465점과 이마 387점으로 보드게임(816점)을 바꾸고, 남은 점수로 무엇을 더 할 수 있나요? 남은 점수를 구하는 식으로 알맞은 것을 고르세요.","options":[{"t":"465 + 387 − 816","correct":true},{"t":"465 + 387 + 816","mis":"M3-1-u1-X12"},{"t":"816 − 465 + 387","mis":"M3-1-u1-X01"},{"t":"465 − 387 − 816","mis":"M3-1-u1-X12"}],"explanation":["먼저 모은 점수 465 + 387을 구해요.","보드게임 점수 816을 빼요.","465 + 387 − 816 = 36점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#7','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',3,'mc','auto','1023점으로 보드게임(816점)을 바꿨어요. 남은 점수는 몇 점인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X08']::text[],true,'{"seq":7,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"1023점으로 보드게임(816점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"207점","correct":true},{"t":"1839점","mis":"M3-1-u1-X12"},{"t":"813점","mis":"M3-1-u1-X07"},{"t":"217점","mis":"M3-1-u1-X08"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 1023 − 816.","일의 자리: 3에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 6 = 7.","1023 − 816 = 207점 남아요."],"variant_rule":{"alt":[{"stem":"1004점으로 축구공(755점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"249점","correct":true},{"t":"1759점","mis":"M3-1-u1-X12"},{"t":"751점","mis":"M3-1-u1-X07"},{"t":"259점","mis":"M3-1-u1-X09"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 1004 − 755.","일의 자리: 4에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 5 = 9.","1004 − 755 = 249점 남아요."]},{"stem":"982점으로 필통(627점)을 바꿨어요. 남은 점수는 몇 점인가요?","options":[{"t":"355점","correct":true},{"t":"1609점","mis":"M3-1-u1-X12"},{"t":"365점","mis":"M3-1-u1-X07"},{"t":"345점","mis":"M3-1-u1-X14"}],"explanation":["바꾸고 남은 점수는 뺄셈 — 982 − 627.","일의 자리: 2에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 7 = 5.","982 − 627 = 355점 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#8','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',4,'essay','teacher','비사치기에서 어깨 465점과 이마 387점을 얻었어요. 보드게임(816점)을 바꿀 수 있는지 판단하고, 바꾼 뒤 남은 점수를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u1-C8","difficulty":4,"kind":"essay","stem":"비사치기에서 어깨 465점과 이마 387점을 얻었어요. 보드게임(816점)을 바꿀 수 있는지 판단하고, 바꾼 뒤 남은 점수를 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 465 + 387 = 852점이다. 852 > 816이므로 보드게임을 바꿀 수 있다. 남은 점수는 852 − 816 = 36점이다(어림 약 850 − 820 = 30과 비슷하다).","scoring_points":["852점을 구했는가","816과 견주어 바꿀 수 있다고 판단했는가","36점을 구했는가"]},"explanation":["모은 점수는 852점이에요.","852 > 816 — 바꿀 수 있어요.","852 − 816 = 36점 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#9','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',4,'essay','teacher','배 359점과 손등 318점으로 축구공(755점)을 바꿀 수 있는지, 바꿀 수 없다면 몇 점이 더 필요한지 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u1-C8","difficulty":4,"kind":"essay","stem":"배 359점과 손등 318점으로 축구공(755점)을 바꿀 수 있는지, 바꿀 수 없다면 몇 점이 더 필요한지 구해 보세요.","answer_guide":{"answer":"예: 359 + 318 = 677점이다. 677 < 755이므로 바꿀 수 없다. 더 필요한 점수는 755 − 677 = 78점이다.","scoring_points":["677점을 구했는가","바꿀 수 없다고 판단했는가","78점을 구했는가"]},"explanation":["359 + 318 = 677점이에요.","677 < 755 — 바꿀 수 없어요.","755 − 677 = 78점 더 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_L08_challenge#10','math',3,1,'u1','L08','g3_1_math_u1_L08_challenge','lesson_challenge','M3-1-u1-C8',4,'sa','auto','배 359점과 손등 318점을 얻었어요. 축구공(755점)을 바꾸려면 몇 점이 더 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u1-C8","difficulty":4,"kind":"sa","stem":"배 359점과 손등 318점을 얻었어요. 축구공(755점)을 바꾸려면 몇 점이 더 필요한가요? 숫자로 쓰세요.","answer":["78"],"explanation":["모은 점수: 359 + 318 = 677점.","축구공 755점과의 차를 구해요.","755 − 677 = 78점이에요."],"variant_rule":{"alt":[{"stem":"발등 234점과 무릎 276점을 얻었어요. 줄넘기(543점)를 바꾸려면 몇 점이 더 필요한가요? 숫자로 쓰세요.","answer":["33"],"explanation":["234 + 276 = 510점.","543과의 차를 구해요.","543 − 510 = 33점이에요."]},{"stem":"손등 318점과 무릎 276점을 얻었어요. 필통(627점)을 바꾸려면 몇 점이 더 필요한가요? 숫자로 쓰세요.","answer":["33"],"explanation":["318 + 276 = 594점.","627과의 차를 구해요.","627 − 594 = 33점이에요."]},{"stem":"발등 234점과 이마 387점을 얻었어요. 필통(627점)을 바꾸려면 몇 점이 더 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["234 + 387 = 621점.","627과의 차를 구해요.","627 − 621 = 6점이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#1','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C1',1,'mc','auto','300 + 236은 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"300 + 236은 얼마인가요?","options":[{"t":"536","correct":true},{"t":"546","mis":"M3-1-u1-X14"},{"t":"526","mis":"M3-1-u1-X14"},{"t":"636","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 6 = 6.","십의 자리: 0 + 3 = 3.","백의 자리: 3 + 2 = 5 — 그래서 300 + 236 = 536이에요."],"variant_rule":{"alt":[{"stem":"330 + 259는 얼마인가요?","options":[{"t":"589","correct":true},{"t":"599","mis":"M3-1-u1-X14"},{"t":"579","mis":"M3-1-u1-X14"},{"t":"689","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 9 = 9.","십의 자리: 3 + 5 = 8.","백의 자리: 3 + 2 = 5 — 그래서 330 + 259 = 589예요."]},{"stem":"421 + 275는 얼마인가요?","options":[{"t":"696","correct":true},{"t":"706","mis":"M3-1-u1-X14"},{"t":"686","mis":"M3-1-u1-X14"},{"t":"796","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1 + 5 = 6.","십의 자리: 2 + 7 = 9.","백의 자리: 4 + 2 = 6 — 그래서 421 + 275 = 696이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#2','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C1',2,'mc','auto','도서관에 동화책이 542권, 과학책이 111권 있어요. 책은 모두 몇 권인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"도서관에 동화책이 542권, 과학책이 111권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"653권","correct":true},{"t":"431권","mis":"M3-1-u1-X12"},{"t":"663권","mis":"M3-1-u1-X14"},{"t":"643권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 542 + 111.","십의 자리: 4 + 1 = 5.","542 + 111 = 653 — 653권이에요."],"variant_rule":{"alt":[{"stem":"도서관에 동화책이 555권, 과학책이 300권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"855권","correct":true},{"t":"255권","mis":"M3-1-u1-X12"},{"t":"865권","mis":"M3-1-u1-X14"},{"t":"845권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 555 + 300.","십의 자리: 5 + 0 = 5.","555 + 300 = 855 — 855권이에요."]},{"stem":"도서관에 동화책이 143권, 과학책이 511권 있어요. 책은 모두 몇 권인가요?","options":[{"t":"654권","correct":true},{"t":"368권","mis":"M3-1-u1-X12"},{"t":"664권","mis":"M3-1-u1-X14"},{"t":"644권","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 143 + 511.","십의 자리: 4 + 1 = 5.","143 + 511 = 654 — 654권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#3','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C2',1,'mc','auto','423 + 568은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":3,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"423 + 568은 얼마인가요?","options":[{"t":"991","correct":true},{"t":"981","mis":"M3-1-u1-X02"},{"t":"1081","mis":"M3-1-u1-X03"},{"t":"9811","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 3 + 8 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 2 + 6 + 1 = 9.","백의 자리: 4 + 5 = 9 — 그래서 423 + 568 = 991이에요."],"variant_rule":{"alt":[{"stem":"182 + 331은 얼마인가요?","options":[{"t":"513","correct":true},{"t":"413","mis":"M3-1-u1-X02"},{"t":"523","mis":"M3-1-u1-X14"},{"t":"503","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 1 = 3.","십의 자리: 8 + 3 = 11 — 백의 자리로 받아올려요.","백의 자리: 1 + 3 + 1 = 5 — 그래서 182 + 331 = 513이에요."]},{"stem":"426 + 256은 얼마인가요?","options":[{"t":"682","correct":true},{"t":"672","mis":"M3-1-u1-X02"},{"t":"772","mis":"M3-1-u1-X03"},{"t":"6712","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 6 + 6 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 2 + 5 + 1 = 8.","백의 자리: 4 + 2 = 6 — 그래서 426 + 256 = 682예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#4','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C2',3,'sa','auto','117 + 669를 세로셈으로 계산해요. 십의 자리에서는 1 + 6에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":3,"kind":"sa","stem":"117 + 669를 세로셈으로 계산해요. 십의 자리에서는 1 + 6에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리: 7 + 9 = 16 — 십의 자리로 1을 받아올려요.","십의 자리: 1 + 6 + 1 = 8.","받아올림한 1을 빠뜨리면 7이 되어 틀려요."],"variant_rule":{"alt":[{"stem":"308 + 452를 세로셈으로 계산해요. 십의 자리에서는 0 + 5에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리: 8 + 2 = 10 — 십의 자리로 1을 받아올려요.","십의 자리: 0 + 5 + 1 = 6.","받아올림한 1을 빠뜨리면 5가 되어 틀려요."]},{"stem":"108 + 643을 세로셈으로 계산해요. 십의 자리에서는 0 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리: 8 + 3 = 11 — 십의 자리로 1을 받아올려요.","십의 자리: 0 + 4 + 1 = 5.","받아올림한 1을 빠뜨리면 4가 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#5','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C2',3,'ox','auto','279 + 211 = 480이에요.',ARRAY['M3-1-u1-X02']::text[],true,'{"seq":5,"concept":"M3-1-u1-C2","difficulty":3,"kind":"ox","stem":"279 + 211 = 480이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 490이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"mis":"M3-1-u1-X02","explanation":["일의 자리: 9 + 1 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 7 + 1 + 1 = 9.","바른 답은 490이에요. 480은 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"311 + 629 = 930이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 940이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 1 + 9 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 1 + 2 + 1 = 4.","바른 답은 940이에요. 930은 받아올림을 빠뜨린 값이에요."]},{"stem":"780 + 126 = 806이에요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 906이 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 0 + 6 = 6.","십의 자리: 8 + 2 = 10 — 백의 자리로 받아올려요.","바른 답은 906이에요. 806은 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#6','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C3',1,'mc','auto','395 + 333을 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":6,"concept":"M3-1-u1-C3","difficulty":1,"kind":"mc","stem":"395 + 333을 어림하면 약 얼마인가요?","options":[{"t":"약 700","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X14"}],"explanation":["395는 약 400, 333은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","400 + 300 = 700 — 약 700이에요. 실제 합 728과 비슷해요."],"variant_rule":{"alt":[{"stem":"480 + 272를 어림하면 약 얼마인가요?","options":[{"t":"약 800","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X11"}],"explanation":["480은 약 500, 272는 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","500 + 300 = 800 — 약 800이에요. 실제 합 752와 비슷해요."]},{"stem":"136 + 147을 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 100","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X14"}],"explanation":["136은 약 100, 147은 약 100으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","100 + 100 = 200 — 약 200이에요. 실제 합 283과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#7','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C3',2,'mc','auto','936 − 774를 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14','M3-1-u1-X12']::text[],true,'{"seq":7,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"936 − 774를 어림하면 약 얼마인가요?","options":[{"t":"약 100","correct":true},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X14"},{"t":"약 1700","mis":"M3-1-u1-X12"}],"explanation":["936은 약 900, 774는 약 800으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","900 − 800 = 100 — 약 100이에요. 실제 차 162와 비슷해요."],"variant_rule":{"alt":[{"stem":"627 − 283을 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 400","mis":"M3-1-u1-X11"},{"t":"약 200","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X14"}],"explanation":["627은 약 600, 283은 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","600 − 300 = 300 — 약 300이에요. 실제 차 344와 비슷해요."]},{"stem":"520 − 111을 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 600","mis":"M3-1-u1-X14"}],"explanation":["520은 약 500, 111은 약 100으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","500 − 100 = 400 — 약 400이에요. 실제 차 409와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#8','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C4',1,'mc','auto','485 + 196은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":8,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"485 + 196은 얼마인가요?","options":[{"t":"681","correct":true},{"t":"571","mis":"M3-1-u1-X02"},{"t":"581","mis":"M3-1-u1-X05"},{"t":"691","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 + 6 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 8 + 9 + 1 = 18 — 백의 자리로 받아올려요.","백의 자리: 4 + 1 + 1 = 6 — 그래서 485 + 196 = 681이에요."],"variant_rule":{"alt":[{"stem":"476 + 386은 얼마인가요?","options":[{"t":"862","correct":true},{"t":"752","mis":"M3-1-u1-X02"},{"t":"762","mis":"M3-1-u1-X05"},{"t":"872","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 6 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 7 + 8 + 1 = 16 — 백의 자리로 받아올려요.","백의 자리: 4 + 3 + 1 = 8 — 그래서 476 + 386 = 862예요."]},{"stem":"382 + 139는 얼마인가요?","options":[{"t":"521","correct":true},{"t":"411","mis":"M3-1-u1-X02"},{"t":"421","mis":"M3-1-u1-X05"},{"t":"531","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 9 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 8 + 3 + 1 = 12 — 백의 자리로 받아올려요.","백의 자리: 3 + 1 + 1 = 5 — 그래서 382 + 139 = 521이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#9','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C4',2,'mc','auto','974 + 551은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X06']::text[],true,'{"seq":9,"concept":"M3-1-u1-C4","difficulty":2,"kind":"mc","stem":"974 + 551은 얼마인가요?","options":[{"t":"1525","correct":true},{"t":"425","mis":"M3-1-u1-X02"},{"t":"1425","mis":"M3-1-u1-X05"},{"t":"525","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 4 + 1 = 5.","십의 자리: 7 + 5 = 12 — 백의 자리로 받아올려요.","백의 자리: 9 + 5 + 1 = 15 — 그래서 974 + 551 = 1525예요."],"variant_rule":{"alt":[{"stem":"983 + 122는 얼마인가요?","options":[{"t":"1105","correct":true},{"t":"5","mis":"M3-1-u1-X02"},{"t":"1005","mis":"M3-1-u1-X05"},{"t":"105","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 3 + 2 = 5.","십의 자리: 8 + 2 = 10 — 백의 자리로 받아올려요.","백의 자리: 9 + 1 + 1 = 11 — 그래서 983 + 122 = 1105예요."]},{"stem":"776 + 428은 얼마인가요?","options":[{"t":"1204","correct":true},{"t":"194","mis":"M3-1-u1-X02"},{"t":"1104","mis":"M3-1-u1-X05"},{"t":"204","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 6 + 8 = 14 — 10을 십의 자리로 받아올리고 4를 써요.","십의 자리: 7 + 2 + 1 = 10 — 백의 자리로 받아올려요.","백의 자리: 7 + 4 + 1 = 12 — 그래서 776 + 428 = 1204예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
