INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#11','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C5',1,'mc','auto','722 − 111은 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":11,"concept":"M3-1-u1-C5","difficulty":1,"kind":"mc","stem":"722 − 111은 얼마인가요?","options":[{"t":"611","correct":true},{"t":"621","mis":"M3-1-u1-X14"},{"t":"601","mis":"M3-1-u1-X14"},{"t":"711","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 − 1 = 1.","십의 자리: 2 − 1 = 1.","백의 자리: 7 − 1 = 6 — 그래서 722 − 111 = 611이에요."],"variant_rule":{"alt":[{"stem":"889 − 170은 얼마인가요?","options":[{"t":"719","correct":true},{"t":"729","mis":"M3-1-u1-X14"},{"t":"709","mis":"M3-1-u1-X14"},{"t":"819","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 9 − 0 = 9.","십의 자리: 8 − 7 = 1.","백의 자리: 8 − 1 = 7 — 그래서 889 − 170 = 719예요."]},{"stem":"945 − 205는 얼마인가요?","options":[{"t":"740","correct":true},{"t":"750","mis":"M3-1-u1-X14"},{"t":"730","mis":"M3-1-u1-X14"},{"t":"840","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 − 5 = 0.","십의 자리: 4 − 0 = 4.","백의 자리: 9 − 2 = 7 — 그래서 945 − 205 = 740이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#12','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C5',2,'mc','auto','색종이 659장 가운데 332장을 썼어요. 남은 색종이는 몇 장인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":12,"concept":"M3-1-u1-C5","difficulty":2,"kind":"mc","stem":"색종이 659장 가운데 332장을 썼어요. 남은 색종이는 몇 장인가요?","options":[{"t":"327장","correct":true},{"t":"991장","mis":"M3-1-u1-X12"},{"t":"337장","mis":"M3-1-u1-X14"},{"t":"317장","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 659 − 332.","일의 자리: 9 − 2 = 7.","659 − 332 = 327 — 327장이에요."],"variant_rule":{"alt":[{"stem":"색종이 948장 가운데 700장을 썼어요. 남은 색종이는 몇 장인가요?","options":[{"t":"248장","correct":true},{"t":"1648장","mis":"M3-1-u1-X12"},{"t":"258장","mis":"M3-1-u1-X14"},{"t":"238장","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 948 − 700.","일의 자리: 8 − 0 = 8.","948 − 700 = 248 — 248장이에요."]},{"stem":"색종이 777장 가운데 400장을 썼어요. 남은 색종이는 몇 장인가요?","options":[{"t":"377장","correct":true},{"t":"1177장","mis":"M3-1-u1-X12"},{"t":"387장","mis":"M3-1-u1-X14"},{"t":"367장","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 777 − 400.","일의 자리: 7 − 0 = 7.","777 − 400 = 377 — 377장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#13','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C6',1,'mc','auto','828 − 150은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X14']::text[],true,'{"seq":13,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"828 − 150은 얼마인가요?","options":[{"t":"678","correct":true},{"t":"738","mis":"M3-1-u1-X07"},{"t":"778","mis":"M3-1-u1-X08"},{"t":"688","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 − 0 = 8.","십의 자리: 2에서 5를 뺄 수 없어 백의 자리에서 빌려요 — 12 − 5 = 7.","백의 자리: 1 줄어든 7 − 1 = 6 — 그래서 828 − 150 = 678이에요."],"variant_rule":{"alt":[{"stem":"971 − 428은 얼마인가요?","options":[{"t":"543","correct":true},{"t":"557","mis":"M3-1-u1-X07"},{"t":"553","mis":"M3-1-u1-X08"},{"t":"533","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 8 = 3.","십의 자리: 1 줄어든 6 − 2 = 4.","백의 자리: 9 − 4 = 5 — 그래서 971 − 428 = 543이에요."]},{"stem":"717 − 154는 얼마인가요?","options":[{"t":"563","correct":true},{"t":"643","mis":"M3-1-u1-X07"},{"t":"663","mis":"M3-1-u1-X08"},{"t":"573","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 − 4 = 3.","십의 자리: 1에서 5를 뺄 수 없어 백의 자리에서 빌려요 — 11 − 5 = 6.","백의 자리: 1 줄어든 6 − 1 = 5 — 그래서 717 − 154 = 563이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#14','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C6',2,'sa','auto','741 − 114를 세로셈으로 계산해요. 일의 자리 1에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u1-C6","difficulty":2,"kind":"sa","stem":"741 − 114를 세로셈으로 계산해요. 일의 자리 1에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.","answer":["11"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 1 + 10 = 11이 돼요.","11 − 4 = 7, 십의 자리는 1 줄어요."],"variant_rule":{"alt":[{"stem":"785 − 208을 세로셈으로 계산해요. 일의 자리 5에서 8을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 8을 빼나요? 숫자로 쓰세요.","answer":["15"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 5 + 10 = 15가 돼요.","15 − 8 = 7, 십의 자리는 1 줄어요."]},{"stem":"732 − 628을 세로셈으로 계산해요. 일의 자리 2에서 8을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 8을 빼나요? 숫자로 쓰세요.","answer":["12"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 2 + 10 = 12가 돼요.","12 − 8 = 4, 십의 자리는 1 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
