INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#19','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C8',1,'mc','auto','비사치기에서 발등으로 234점, 배로 359점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":19,"concept":"M3-1-u1-C8","difficulty":1,"kind":"mc","stem":"비사치기에서 발등으로 234점, 배로 359점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"593점","correct":true},{"t":"583점","mis":"M3-1-u1-X02"},{"t":"683점","mis":"M3-1-u1-X03"},{"t":"5813점","mis":"M3-1-u1-X04"}],"explanation":["모은 점수는 덧셈 — 234 + 359.","십의 자리: 3 + 5 + 1 = 9.","234 + 359 = 593점이에요."],"variant_rule":{"alt":[{"stem":"비사치기에서 손등으로 318점, 무릎으로 276점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"594점","correct":true},{"t":"584점","mis":"M3-1-u1-X02"},{"t":"684점","mis":"M3-1-u1-X03"},{"t":"5814점","mis":"M3-1-u1-X04"}],"explanation":["모은 점수는 덧셈 — 318 + 276.","십의 자리: 1 + 7 + 1 = 9.","318 + 276 = 594점이에요."]},{"stem":"비사치기에서 무릎으로 276점, 발등으로 234점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"510점","correct":true},{"t":"400점","mis":"M3-1-u1-X02"},{"t":"410점","mis":"M3-1-u1-X05"},{"t":"520점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 276 + 234.","십의 자리: 7 + 3 + 1 = 11 — 백의 자리로 받아올려요.","276 + 234 = 510점이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
