INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#24','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C7',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X15']::text[],true,'{"seq":24,"concept":"M3-1-u1-C7","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"833 − 296 = 663","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"551 − 179 = 372","mis":"M3-1-u1-X15"},{"t":"938 − 149 = 789","mis":"M3-1-u1-X15"},{"t":"833 − 368 = 465","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","833 − 296은 받아내림을 하면 537이에요.","663은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"987 − 289 = 702","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"664 − 199 = 465","mis":"M3-1-u1-X15"},{"t":"751 − 166 = 585","mis":"M3-1-u1-X15"},{"t":"954 − 177 = 777","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","987 − 289는 받아내림을 하면 698이에요.","702는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"933 − 668 = 335","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"838 − 299 = 539","mis":"M3-1-u1-X15"},{"t":"640 − 369 = 271","mis":"M3-1-u1-X15"},{"t":"820 − 323 = 497","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","933 − 668은 받아내림을 하면 265예요.","335는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_a#25','math',3,1,'u1','','g3_1_math_u1_review_a','unit_review','M3-1-u1-C4',4,'essay','teacher','세 자리 수의 덧셈에서 받아올림을 빠뜨리지 않으려면 어떻게 하면 좋은지 542 + 279를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u1-C4","difficulty":4,"kind":"essay","stem":"세 자리 수의 덧셈에서 받아올림을 빠뜨리지 않으려면 어떻게 하면 좋은지 542 + 279를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리: 2 + 9 = 11 — 10을 십의 자리로 받아올리고 1을 써요. 십의 자리: 4 + 7 + 1 = 12 — 백의 자리로 받아올려요. 백의 자리: 5 + 2 + 1 = 8 — 그래서 542 + 279 = 821이에요. 받아올림을 자리마다 작게 표시하고, 어림(약 500 + 약 300 = 약 800)과 견주어 점검한다.","scoring_points":["자리마다 바르게 계산했는가","받아올림을 표시하거나 빠뜨리지 않는 방법을 썼는가","821을 구하고 어림과 견주었는가"]},"explanation":["일의 자리: 2 + 9 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 4 + 7 + 1 = 12 — 백의 자리로 받아올려요.","백의 자리: 5 + 2 + 1 = 8 — 그래서 542 + 279 = 821이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#1','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C1',1,'mc','auto','732 + 261은 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"732 + 261은 얼마인가요?","options":[{"t":"993","correct":true},{"t":"1003","mis":"M3-1-u1-X14"},{"t":"983","mis":"M3-1-u1-X14"},{"t":"1093","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 1 = 3.","십의 자리: 3 + 6 = 9.","백의 자리: 7 + 2 = 9 — 그래서 732 + 261 = 993이에요."],"variant_rule":{"alt":[{"stem":"437 + 220은 얼마인가요?","options":[{"t":"657","correct":true},{"t":"667","mis":"M3-1-u1-X14"},{"t":"647","mis":"M3-1-u1-X14"},{"t":"757","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 + 0 = 7.","십의 자리: 3 + 2 = 5.","백의 자리: 4 + 2 = 6 — 그래서 437 + 220 = 657이에요."]},{"stem":"454 + 400은 얼마인가요?","options":[{"t":"854","correct":true},{"t":"864","mis":"M3-1-u1-X14"},{"t":"844","mis":"M3-1-u1-X14"},{"t":"954","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 4 + 0 = 4.","십의 자리: 5 + 0 = 5.","백의 자리: 4 + 4 = 8 — 그래서 454 + 400 = 854예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#2','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C1',2,'mc','auto','온라인 마을에 오전에 322명, 오후에 377명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"온라인 마을에 오전에 322명, 오후에 377명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"699명","correct":true},{"t":"55명","mis":"M3-1-u1-X12"},{"t":"709명","mis":"M3-1-u1-X14"},{"t":"689명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 322 + 377.","십의 자리: 2 + 7 = 9.","322 + 377 = 699 — 699명이에요."],"variant_rule":{"alt":[{"stem":"온라인 마을에 오전에 233명, 오후에 501명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"734명","correct":true},{"t":"268명","mis":"M3-1-u1-X12"},{"t":"744명","mis":"M3-1-u1-X14"},{"t":"724명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 233 + 501.","십의 자리: 3 + 0 = 3.","233 + 501 = 734 — 734명이에요."]},{"stem":"온라인 마을에 오전에 643명, 오후에 320명이 접속했어요. 하루 동안 접속한 사람은 모두 몇 명인가요?","options":[{"t":"963명","correct":true},{"t":"323명","mis":"M3-1-u1-X12"},{"t":"973명","mis":"M3-1-u1-X14"},{"t":"953명","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 643 + 320.","십의 자리: 4 + 2 = 6.","643 + 320 = 963 — 963명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#3','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C2',1,'mc','auto','308 + 557은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":3,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"308 + 557은 얼마인가요?","options":[{"t":"865","correct":true},{"t":"855","mis":"M3-1-u1-X02"},{"t":"955","mis":"M3-1-u1-X03"},{"t":"8515","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 8 + 7 = 15 — 10을 십의 자리로 받아올리고 5를 써요.","십의 자리: 0 + 5 + 1 = 6.","백의 자리: 3 + 5 = 8 — 그래서 308 + 557 = 865예요."],"variant_rule":{"alt":[{"stem":"171 + 331은 얼마인가요?","options":[{"t":"502","correct":true},{"t":"402","mis":"M3-1-u1-X02"},{"t":"512","mis":"M3-1-u1-X14"},{"t":"492","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 1 + 1 = 2.","십의 자리: 7 + 3 = 10 — 백의 자리로 받아올려요.","백의 자리: 1 + 3 + 1 = 5 — 그래서 171 + 331 = 502예요."]},{"stem":"172 + 460은 얼마인가요?","options":[{"t":"632","correct":true},{"t":"532","mis":"M3-1-u1-X02"},{"t":"642","mis":"M3-1-u1-X14"},{"t":"622","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 2 + 0 = 2.","십의 자리: 7 + 6 = 13 — 백의 자리로 받아올려요.","백의 자리: 1 + 4 + 1 = 6 — 그래서 172 + 460 = 632예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#4','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C2',3,'sa','auto','715 + 148을 세로셈으로 계산해요. 십의 자리에서는 1 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":3,"kind":"sa","stem":"715 + 148을 세로셈으로 계산해요. 십의 자리에서는 1 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리: 5 + 8 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 1 + 4 + 1 = 6.","받아올림한 1을 빠뜨리면 5가 되어 틀려요."],"variant_rule":{"alt":[{"stem":"854 + 139를 세로셈으로 계산해요. 십의 자리에서는 5 + 3에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["일의 자리: 4 + 9 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 5 + 3 + 1 = 9.","받아올림한 1을 빠뜨리면 8이 되어 틀려요."]},{"stem":"755 + 215를 세로셈으로 계산해요. 십의 자리에서는 5 + 1에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["일의 자리: 5 + 5 = 10 — 십의 자리로 1을 받아올려요.","십의 자리: 5 + 1 + 1 = 7.","받아올림한 1을 빠뜨리면 6이 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#5','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C2',3,'ox','auto','227 + 245 = 462예요.',ARRAY['M3-1-u1-X02']::text[],true,'{"seq":5,"concept":"M3-1-u1-C2","difficulty":3,"kind":"ox","stem":"227 + 245 = 462예요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 472가 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"mis":"M3-1-u1-X02","explanation":["일의 자리: 7 + 5 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 2 + 4 + 1 = 7.","바른 답은 472예요. 462는 받아올림을 빠뜨린 값이에요."],"variant_rule":{"alt":[{"stem":"178 + 241 = 319예요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 419가 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 8 + 1 = 9.","십의 자리: 7 + 4 = 11 — 백의 자리로 받아올려요.","바른 답은 419예요. 319는 받아올림을 빠뜨린 값이에요."]},{"stem":"358 + 181 = 439예요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더하면 539가 되어서","correct":true},{"t":"같은 자리끼리 더했으니 맞아서","mis":"M3-1-u1-X02"}],"explanation":["일의 자리: 8 + 1 = 9.","십의 자리: 5 + 8 = 13 — 백의 자리로 받아올려요.","바른 답은 539예요. 439는 받아올림을 빠뜨린 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#6','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C3',1,'mc','auto','219 + 405를 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":6,"concept":"M3-1-u1-C3","difficulty":1,"kind":"mc","stem":"219 + 405를 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X14"}],"explanation":["219는 약 200, 405는 약 400으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","200 + 400 = 600 — 약 600이에요. 실제 합 624와 비슷해요."],"variant_rule":{"alt":[{"stem":"110 + 594를 어림하면 약 얼마인가요?","options":[{"t":"약 700","correct":true},{"t":"약 600","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X11"},{"t":"약 900","mis":"M3-1-u1-X14"}],"explanation":["110은 약 100, 594는 약 600으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","100 + 600 = 700 — 약 700이에요. 실제 합 704와 비슷해요."]},{"stem":"220 + 382를 어림하면 약 얼마인가요?","options":[{"t":"약 600","correct":true},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 700","mis":"M3-1-u1-X11"},{"t":"약 800","mis":"M3-1-u1-X14"}],"explanation":["220은 약 200, 382는 약 400으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","200 + 400 = 600 — 약 600이에요. 실제 합 602와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#7','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C3',2,'mc','auto','722 − 309를 어림하면 약 얼마인가요?',ARRAY['M3-1-u1-X11','M3-1-u1-X14']::text[],true,'{"seq":7,"concept":"M3-1-u1-C3","difficulty":2,"kind":"mc","stem":"722 − 309를 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 600","mis":"M3-1-u1-X14"}],"explanation":["722는 약 700, 309는 약 300으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","700 − 300 = 400 — 약 400이에요. 실제 차 413과 비슷해요."],"variant_rule":{"alt":[{"stem":"647 − 248을 어림하면 약 얼마인가요?","options":[{"t":"약 400","correct":true},{"t":"약 500","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 600","mis":"M3-1-u1-X14"}],"explanation":["647은 약 600, 248은 약 200으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","600 − 200 = 400 — 약 400이에요. 실제 차 399와 비슷해요."]},{"stem":"782 − 628을 어림하면 약 얼마인가요?","options":[{"t":"약 200","correct":true},{"t":"약 100","mis":"M3-1-u1-X11"},{"t":"약 300","mis":"M3-1-u1-X11"},{"t":"약 400","mis":"M3-1-u1-X14"}],"explanation":["782는 약 800, 628은 약 600으로 어림해요.","가까운 몇백으로 — 십의 자리가 5 이상이면 올려요.","800 − 600 = 200 — 약 200이에요. 실제 차 154와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#8','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C4',1,'mc','auto','396 + 579는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":8,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"396 + 579는 얼마인가요?","options":[{"t":"975","correct":true},{"t":"865","mis":"M3-1-u1-X02"},{"t":"875","mis":"M3-1-u1-X05"},{"t":"985","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 9 = 15 — 10을 십의 자리로 받아올리고 5를 써요.","십의 자리: 9 + 7 + 1 = 17 — 백의 자리로 받아올려요.","백의 자리: 3 + 5 + 1 = 9 — 그래서 396 + 579 = 975예요."],"variant_rule":{"alt":[{"stem":"184 + 158은 얼마인가요?","options":[{"t":"342","correct":true},{"t":"232","mis":"M3-1-u1-X02"},{"t":"242","mis":"M3-1-u1-X05"},{"t":"352","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 4 + 8 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 8 + 5 + 1 = 14 — 백의 자리로 받아올려요.","백의 자리: 1 + 1 + 1 = 3 — 그래서 184 + 158 = 342예요."]},{"stem":"694 + 137은 얼마인가요?","options":[{"t":"831","correct":true},{"t":"721","mis":"M3-1-u1-X02"},{"t":"731","mis":"M3-1-u1-X05"},{"t":"841","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 4 + 7 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 9 + 3 + 1 = 13 — 백의 자리로 받아올려요.","백의 자리: 6 + 1 + 1 = 8 — 그래서 694 + 137 = 831이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#9','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C4',2,'mc','auto','753 + 453은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X06']::text[],true,'{"seq":9,"concept":"M3-1-u1-C4","difficulty":2,"kind":"mc","stem":"753 + 453은 얼마인가요?","options":[{"t":"1206","correct":true},{"t":"106","mis":"M3-1-u1-X02"},{"t":"1106","mis":"M3-1-u1-X05"},{"t":"206","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 3 + 3 = 6.","십의 자리: 5 + 5 = 10 — 백의 자리로 받아올려요.","백의 자리: 7 + 4 + 1 = 12 — 그래서 753 + 453 = 1206이에요."],"variant_rule":{"alt":[{"stem":"725 + 816은 얼마인가요?","options":[{"t":"1541","correct":true},{"t":"531","mis":"M3-1-u1-X02"},{"t":"1531","mis":"M3-1-u1-X05"},{"t":"541","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 5 + 6 = 11 — 10을 십의 자리로 받아올리고 1을 써요.","십의 자리: 2 + 1 + 1 = 4.","백의 자리: 7 + 8 = 15 — 그래서 725 + 816 = 1541이에요."]},{"stem":"762 + 366은 얼마인가요?","options":[{"t":"1128","correct":true},{"t":"28","mis":"M3-1-u1-X02"},{"t":"1028","mis":"M3-1-u1-X05"},{"t":"128","mis":"M3-1-u1-X06"}],"explanation":["일의 자리: 2 + 6 = 8.","십의 자리: 6 + 6 = 12 — 백의 자리로 받아올려요.","백의 자리: 7 + 3 + 1 = 11 — 그래서 762 + 366 = 1128이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
