INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#12','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C5',2,'mc','auto','도서관에 책이 753권 있었어요. 그중 300권을 빌려 갔어요. 남은 책은 몇 권인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":12,"concept":"M3-1-u1-C5","difficulty":2,"kind":"mc","stem":"도서관에 책이 753권 있었어요. 그중 300권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"453권","correct":true},{"t":"1053권","mis":"M3-1-u1-X12"},{"t":"463권","mis":"M3-1-u1-X14"},{"t":"443권","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 753 − 300.","일의 자리: 3 − 0 = 3.","753 − 300 = 453 — 453권이에요."],"variant_rule":{"alt":[{"stem":"도서관에 책이 679권 있었어요. 그중 241권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"438권","correct":true},{"t":"920권","mis":"M3-1-u1-X12"},{"t":"448권","mis":"M3-1-u1-X14"},{"t":"428권","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 679 − 241.","일의 자리: 9 − 1 = 8.","679 − 241 = 438 — 438권이에요."]},{"stem":"도서관에 책이 968권 있었어요. 그중 106권을 빌려 갔어요. 남은 책은 몇 권인가요?","options":[{"t":"862권","correct":true},{"t":"1074권","mis":"M3-1-u1-X12"},{"t":"872권","mis":"M3-1-u1-X14"},{"t":"852권","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 968 − 106.","일의 자리: 8 − 6 = 2.","968 − 106 = 862 — 862권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#13','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C6',1,'mc','auto','824 − 191은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X14']::text[],true,'{"seq":13,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"824 − 191은 얼마인가요?","options":[{"t":"633","correct":true},{"t":"773","mis":"M3-1-u1-X07"},{"t":"733","mis":"M3-1-u1-X08"},{"t":"643","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 4 − 1 = 3.","십의 자리: 2에서 9를 뺄 수 없어 백의 자리에서 빌려요 — 12 − 9 = 3.","백의 자리: 1 줄어든 7 − 1 = 6 — 그래서 824 − 191 = 633이에요."],"variant_rule":{"alt":[{"stem":"925 − 680은 얼마인가요?","options":[{"t":"245","correct":true},{"t":"365","mis":"M3-1-u1-X07"},{"t":"345","mis":"M3-1-u1-X08"},{"t":"255","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 − 0 = 5.","십의 자리: 2에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 12 − 8 = 4.","백의 자리: 1 줄어든 8 − 6 = 2 — 그래서 925 − 680 = 245예요."]},{"stem":"777 − 181은 얼마인가요?","options":[{"t":"596","correct":true},{"t":"616","mis":"M3-1-u1-X07"},{"t":"696","mis":"M3-1-u1-X08"},{"t":"606","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 − 1 = 6.","십의 자리: 7에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 17 − 8 = 9.","백의 자리: 1 줄어든 6 − 1 = 5 — 그래서 777 − 181 = 596이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#14','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C6',2,'sa','auto','880 − 654를 세로셈으로 계산해요. 일의 자리 0에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u1-C6","difficulty":2,"kind":"sa","stem":"880 − 654를 세로셈으로 계산해요. 일의 자리 0에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 4 = 6, 십의 자리는 1 줄어요."],"variant_rule":{"alt":[{"stem":"751 − 606을 세로셈으로 계산해요. 일의 자리 1에서 6을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 6을 빼나요? 숫자로 쓰세요.","answer":["11"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 1 + 10 = 11이 돼요.","11 − 6 = 5, 십의 자리는 1 줄어요."]},{"stem":"875 − 337을 세로셈으로 계산해요. 일의 자리 5에서 7을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 7을 빼나요? 숫자로 쓰세요.","answer":["15"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 5 + 10 = 15가 돼요.","15 − 7 = 8, 십의 자리는 1 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#15','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C6',3,'ox','auto','864 − 694 = 270이에요.',ARRAY['M3-1-u1-X08']::text[],true,'{"seq":15,"concept":"M3-1-u1-C6","difficulty":3,"kind":"ox","stem":"864 − 694 = 270이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 170이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"mis":"M3-1-u1-X08","explanation":["일의 자리: 4 − 4 = 0.","십의 자리: 6에서 9를 뺄 수 없어 백의 자리에서 빌려요 — 16 − 9 = 7.","바른 답은 170이에요. 270은 빌려준 자리를 줄이지 않은 값이에요."],"variant_rule":{"alt":[{"stem":"548 − 388 = 260이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 160이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 8 − 8 = 0.","십의 자리: 4에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 14 − 8 = 6.","바른 답은 160이에요. 260은 빌려준 자리를 줄이지 않은 값이에요."]},{"stem":"854 − 638 = 226이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 216이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 4에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 8 = 6.","십의 자리: 1 줄어든 4 − 3 = 1.","바른 답은 216이에요. 226은 빌려준 자리를 줄이지 않은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#16','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C7',1,'mc','auto','321 − 135는 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X10']::text[],true,'{"seq":16,"concept":"M3-1-u1-C7","difficulty":1,"kind":"mc","stem":"321 − 135는 얼마인가요?","options":[{"t":"186","correct":true},{"t":"214","mis":"M3-1-u1-X07"},{"t":"196","mis":"M3-1-u1-X08"},{"t":"286","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 1에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 5 = 6.","십의 자리: 1 줄어든 1에서 3을 뺄 수 없어 백의 자리에서 빌려요 — 11 − 3 = 8.","백의 자리: 1 줄어든 2 − 1 = 1 — 그래서 321 − 135 = 186이에요."],"variant_rule":{"alt":[{"stem":"832 − 193은 얼마인가요?","options":[{"t":"639","correct":true},{"t":"761","mis":"M3-1-u1-X07"},{"t":"649","mis":"M3-1-u1-X08"},{"t":"739","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 2에서 3을 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 3 = 9.","십의 자리: 1 줄어든 2에서 9를 뺄 수 없어 백의 자리에서 빌려요 — 12 − 9 = 3.","백의 자리: 1 줄어든 7 − 1 = 6 — 그래서 832 − 193 = 639예요."]},{"stem":"950 − 751은 얼마인가요?","options":[{"t":"199","correct":true},{"t":"201","mis":"M3-1-u1-X07"},{"t":"209","mis":"M3-1-u1-X08"},{"t":"299","mis":"M3-1-u1-X10"}],"explanation":["일의 자리: 0에서 1을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 1 = 9.","십의 자리: 1 줄어든 4에서 5를 뺄 수 없어 백의 자리에서 빌려요 — 14 − 5 = 9.","백의 자리: 1 줄어든 8 − 7 = 1 — 그래서 950 − 751 = 199예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
