INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#18','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C7',4,'sa','auto','423 − 385는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-1-u1-C7","difficulty":4,"kind":"sa","stem":"423 − 385는 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["일의 자리: 3에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 5 = 8.","십의 자리: 1 줄어든 1에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 11 − 8 = 3.","백의 자리는 3 − 3 = 0이라 쓰지 않아요 — 그래서 423 − 385 = 38이에요."],"variant_rule":{"alt":[{"stem":"661 − 598은 얼마인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["일의 자리: 1에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 8 = 3.","십의 자리: 1 줄어든 5에서 9를 뺄 수 없어 백의 자리에서 빌려요 — 15 − 9 = 6.","백의 자리는 5 − 5 = 0이라 쓰지 않아요 — 그래서 661 − 598 = 63이에요."]},{"stem":"533 − 464는 얼마인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["일의 자리: 3에서 4를 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 4 = 9.","십의 자리: 1 줄어든 2에서 6을 뺄 수 없어 백의 자리에서 빌려요 — 12 − 6 = 6.","백의 자리는 4 − 4 = 0이라 쓰지 않아요 — 그래서 533 − 464 = 69예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#19','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C8',1,'mc','auto','비사치기에서 손등으로 318점, 어깨로 465점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":19,"concept":"M3-1-u1-C8","difficulty":1,"kind":"mc","stem":"비사치기에서 손등으로 318점, 어깨로 465점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"783점","correct":true},{"t":"773점","mis":"M3-1-u1-X02"},{"t":"873점","mis":"M3-1-u1-X03"},{"t":"7713점","mis":"M3-1-u1-X04"}],"explanation":["모은 점수는 덧셈 — 318 + 465.","십의 자리: 1 + 6 + 1 = 8.","318 + 465 = 783점이에요."],"variant_rule":{"alt":[{"stem":"비사치기에서 배로 359점, 머리로 492점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"851점","correct":true},{"t":"741점","mis":"M3-1-u1-X02"},{"t":"751점","mis":"M3-1-u1-X05"},{"t":"861점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 359 + 492.","십의 자리: 5 + 9 + 1 = 15 — 백의 자리로 받아올려요.","359 + 492 = 851점이에요."]},{"stem":"비사치기에서 발등으로 234점, 이마로 387점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"621점","correct":true},{"t":"511점","mis":"M3-1-u1-X02"},{"t":"521점","mis":"M3-1-u1-X05"},{"t":"631점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 234 + 387.","십의 자리: 3 + 8 + 1 = 12 — 백의 자리로 받아올려요.","234 + 387 = 621점이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
