INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#22','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C8',3,'mc','auto','어깨 465점과 이마 387점을 얻었어요. 이 점수로 보드게임(816점)을 바꿀 수 있나요?',ARRAY['M3-1-u1-X13','M3-1-u1-X15']::text[],true,'{"seq":22,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"어깨 465점과 이마 387점을 얻었어요. 이 점수로 보드게임(816점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"어깨 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 465 + 387 = 852.","852점과 보드게임 816점을 견주면 852 > 816이에요.","그래서 바꿀 수 있어요."],"variant_rule":{"alt":[{"stem":"머리 492점과 배 359점을 얻었어요. 이 점수로 보드게임(816점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"머리 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 492 + 359 = 851.","851점과 보드게임 816점을 견주면 851 > 816이에요.","그래서 바꿀 수 있어요."]},{"stem":"이마 387점과 머리 492점을 얻었어요. 이 점수로 퍼즐(708점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"이마 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 387 + 492 = 879.","879점과 퍼즐 708점을 견주면 879 > 708이에요.","그래서 바꿀 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
