INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#24','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C7',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X15']::text[],true,'{"seq":24,"concept":"M3-1-u1-C7","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"687 − 499 = 212","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"372 − 197 = 175","mis":"M3-1-u1-X15"},{"t":"980 − 392 = 588","mis":"M3-1-u1-X15"},{"t":"464 − 298 = 166","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","687 − 499는 받아내림을 하면 188이에요.","212는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"714 − 488 = 374","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"913 − 118 = 795","mis":"M3-1-u1-X15"},{"t":"320 − 193 = 127","mis":"M3-1-u1-X15"},{"t":"565 − 168 = 397","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","714 − 488은 받아내림을 하면 226이에요.","374는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"711 − 519 = 208","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"816 − 237 = 579","mis":"M3-1-u1-X15"},{"t":"610 − 493 = 117","mis":"M3-1-u1-X15"},{"t":"844 − 398 = 446","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","711 − 519는 받아내림을 하면 192예요.","208은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_b#25','math',3,1,'u1','','g3_1_math_u1_review_b','unit_review','M3-1-u1-C7',4,'essay','teacher','세 자리 수의 뺄셈에서 받아내림을 빠뜨리지 않으려면 어떻게 하면 좋은지 843 − 418을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u1-C7","difficulty":4,"kind":"essay","stem":"세 자리 수의 뺄셈에서 받아내림을 빠뜨리지 않으려면 어떻게 하면 좋은지 843 − 418을 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리: 3에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 8 = 5. 십의 자리: 1 줄어든 3 − 1 = 2. 백의 자리: 8 − 4 = 4 — 그래서 843 − 418 = 425예요. 받아내림을 자리마다 작게 표시하고, 어림(약 800 − 약 400 = 약 400)과 견주어 점검한다.","scoring_points":["자리마다 바르게 계산했는가","받아내림을 표시하거나 빠뜨리지 않는 방법을 썼는가","425를 구하고 어림과 견주었는가"]},"explanation":["일의 자리: 3에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 8 = 5.","십의 자리: 1 줄어든 3 − 1 = 2.","백의 자리: 8 − 4 = 4 — 그래서 843 − 418 = 425예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
