INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#2','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C1',2,'mc','auto','빵집에서 빵을 오전에 236개, 오후에 113개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":2,"concept":"M3-1-u1-C1","difficulty":2,"kind":"mc","stem":"빵집에서 빵을 오전에 236개, 오후에 113개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"349개","correct":true},{"t":"123개","mis":"M3-1-u1-X12"},{"t":"359개","mis":"M3-1-u1-X14"},{"t":"339개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 236 + 113.","십의 자리: 3 + 1 = 4.","236 + 113 = 349 — 349개예요."],"variant_rule":{"alt":[{"stem":"빵집에서 빵을 오전에 435개, 오후에 124개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"559개","correct":true},{"t":"311개","mis":"M3-1-u1-X12"},{"t":"569개","mis":"M3-1-u1-X14"},{"t":"549개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 435 + 124.","십의 자리: 3 + 2 = 5.","435 + 124 = 559 — 559개예요."]},{"stem":"빵집에서 빵을 오전에 402개, 오후에 202개 팔았어요. 하루 동안 판 빵은 모두 몇 개인가요?","options":[{"t":"604개","correct":true},{"t":"200개","mis":"M3-1-u1-X12"},{"t":"614개","mis":"M3-1-u1-X14"},{"t":"594개","mis":"M3-1-u1-X14"}],"explanation":["모두 몇인지 구하니 덧셈이에요 — 402 + 202.","십의 자리: 0 + 0 = 0.","402 + 202 = 604 — 604개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#3','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C2',1,'mc','auto','359 + 315는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":3,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"359 + 315는 얼마인가요?","options":[{"t":"674","correct":true},{"t":"664","mis":"M3-1-u1-X02"},{"t":"764","mis":"M3-1-u1-X03"},{"t":"6614","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 9 + 5 = 14 — 10을 십의 자리로 받아올리고 4를 써요.","십의 자리: 5 + 1 + 1 = 7.","백의 자리: 3 + 3 = 6 — 그래서 359 + 315 = 674예요."],"variant_rule":{"alt":[{"stem":"127 + 282는 얼마인가요?","options":[{"t":"409","correct":true},{"t":"309","mis":"M3-1-u1-X02"},{"t":"419","mis":"M3-1-u1-X14"},{"t":"399","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 7 + 2 = 9.","십의 자리: 2 + 8 = 10 — 백의 자리로 받아올려요.","백의 자리: 1 + 2 + 1 = 4 — 그래서 127 + 282 = 409예요."]},{"stem":"134 + 209는 얼마인가요?","options":[{"t":"343","correct":true},{"t":"333","mis":"M3-1-u1-X02"},{"t":"433","mis":"M3-1-u1-X03"},{"t":"3313","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 4 + 9 = 13 — 10을 십의 자리로 받아올리고 3을 써요.","십의 자리: 3 + 0 + 1 = 4.","백의 자리: 1 + 2 = 3 — 그래서 134 + 209 = 343이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#4','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C2',3,'sa','auto','127 + 256을 세로셈으로 계산해요. 십의 자리에서는 2 + 5에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":3,"kind":"sa","stem":"127 + 256을 세로셈으로 계산해요. 십의 자리에서는 2 + 5에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리: 7 + 6 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 2 + 5 + 1 = 8.","받아올림한 1을 빠뜨리면 7이 되어 틀려요."],"variant_rule":{"alt":[{"stem":"669 + 217을 세로셈으로 계산해요. 십의 자리에서는 6 + 1에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리: 9 + 7 = 16 — 십의 자리로 1을 받아올려요.","십의 자리: 6 + 1 + 1 = 8.","받아올림한 1을 빠뜨리면 7이 되어 틀려요."]},{"stem":"435 + 148을 세로셈으로 계산해요. 십의 자리에서는 3 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["일의 자리: 5 + 8 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 3 + 4 + 1 = 8.","받아올림한 1을 빠뜨리면 7이 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
