INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#8','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C4',1,'mc','auto','348 + 466은 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":8,"concept":"M3-1-u1-C4","difficulty":1,"kind":"mc","stem":"348 + 466은 얼마인가요?","options":[{"t":"814","correct":true},{"t":"704","mis":"M3-1-u1-X02"},{"t":"714","mis":"M3-1-u1-X05"},{"t":"824","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 + 6 = 14 — 10을 십의 자리로 받아올리고 4를 써요.","십의 자리: 4 + 6 + 1 = 11 — 백의 자리로 받아올려요.","백의 자리: 3 + 4 + 1 = 8 — 그래서 348 + 466 = 814예요."],"variant_rule":{"alt":[{"stem":"249 + 463은 얼마인가요?","options":[{"t":"712","correct":true},{"t":"602","mis":"M3-1-u1-X02"},{"t":"612","mis":"M3-1-u1-X05"},{"t":"722","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 9 + 3 = 12 — 10을 십의 자리로 받아올리고 2를 써요.","십의 자리: 4 + 6 + 1 = 11 — 백의 자리로 받아올려요.","백의 자리: 2 + 4 + 1 = 7 — 그래서 249 + 463 = 712예요."]},{"stem":"195 + 339는 얼마인가요?","options":[{"t":"534","correct":true},{"t":"424","mis":"M3-1-u1-X02"},{"t":"434","mis":"M3-1-u1-X05"},{"t":"544","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5 + 9 = 14 — 10을 십의 자리로 받아올리고 4를 써요.","십의 자리: 9 + 3 + 1 = 13 — 백의 자리로 받아올려요.","백의 자리: 1 + 3 + 1 = 5 — 그래서 195 + 339 = 534예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
