INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#12','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C5',2,'mc','auto','사탕이 368개 있었어요. 친구들에게 115개를 나눠 주었어요. 남은 사탕은 몇 개인가요?',ARRAY['M3-1-u1-X12','M3-1-u1-X14']::text[],true,'{"seq":12,"concept":"M3-1-u1-C5","difficulty":2,"kind":"mc","stem":"사탕이 368개 있었어요. 친구들에게 115개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"253개","correct":true},{"t":"483개","mis":"M3-1-u1-X12"},{"t":"263개","mis":"M3-1-u1-X14"},{"t":"243개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 368 − 115.","일의 자리: 8 − 5 = 3.","368 − 115 = 253 — 253개예요."],"variant_rule":{"alt":[{"stem":"사탕이 347개 있었어요. 친구들에게 103개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"244개","correct":true},{"t":"450개","mis":"M3-1-u1-X12"},{"t":"254개","mis":"M3-1-u1-X14"},{"t":"234개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 347 − 103.","일의 자리: 7 − 3 = 4.","347 − 103 = 244 — 244개예요."]},{"stem":"사탕이 962개 있었어요. 친구들에게 861개를 나눠 주었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"101개","correct":true},{"t":"1823개","mis":"M3-1-u1-X12"},{"t":"111개","mis":"M3-1-u1-X14"},{"t":"91개","mis":"M3-1-u1-X14"}],"explanation":["남은 수를 구하니 뺄셈이에요 — 962 − 861.","일의 자리: 2 − 1 = 1.","962 − 861 = 101 — 101개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#13','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C6',1,'mc','auto','924 − 418은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X08','M3-1-u1-X14']::text[],true,'{"seq":13,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"924 − 418은 얼마인가요?","options":[{"t":"506","correct":true},{"t":"514","mis":"M3-1-u1-X07"},{"t":"516","mis":"M3-1-u1-X08"},{"t":"496","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 4에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 14 − 8 = 6.","십의 자리: 1 줄어든 1 − 1 = 0.","백의 자리: 9 − 4 = 5 — 그래서 924 − 418 = 506이에요."],"variant_rule":{"alt":[{"stem":"880 − 732는 얼마인가요?","options":[{"t":"148","correct":true},{"t":"152","mis":"M3-1-u1-X07"},{"t":"158","mis":"M3-1-u1-X08"},{"t":"138","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0에서 2를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 2 = 8.","십의 자리: 1 줄어든 7 − 3 = 4.","백의 자리: 8 − 7 = 1 — 그래서 880 − 732 = 148이에요."]},{"stem":"859 − 468은 얼마인가요?","options":[{"t":"391","correct":true},{"t":"411","mis":"M3-1-u1-X07"},{"t":"491","mis":"M3-1-u1-X08"},{"t":"401","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 9 − 8 = 1.","십의 자리: 5에서 6을 뺄 수 없어 백의 자리에서 빌려요 — 15 − 6 = 9.","백의 자리: 1 줄어든 7 − 4 = 3 — 그래서 859 − 468 = 391이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#14','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C6',2,'sa','auto','820 − 206을 세로셈으로 계산해요. 일의 자리 0에서 6을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 6을 빼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u1-C6","difficulty":2,"kind":"sa","stem":"820 − 206을 세로셈으로 계산해요. 일의 자리 0에서 6을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 6을 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 6 = 4, 십의 자리는 1 줄어요."],"variant_rule":{"alt":[{"stem":"683 − 224를 세로셈으로 계산해요. 일의 자리 3에서 4를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 4를 빼나요? 숫자로 쓰세요.","answer":["13"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 3 + 10 = 13이 돼요.","13 − 4 = 9, 십의 자리는 1 줄어요."]},{"stem":"750 − 503을 세로셈으로 계산해요. 일의 자리 0에서 3을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 3을 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 3 = 7, 십의 자리는 1 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#15','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C6',3,'ox','auto','616 − 164 = 552예요.',ARRAY['M3-1-u1-X08']::text[],true,'{"seq":15,"concept":"M3-1-u1-C6","difficulty":3,"kind":"ox","stem":"616 − 164 = 552예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 452가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"mis":"M3-1-u1-X08","explanation":["일의 자리: 6 − 4 = 2.","십의 자리: 1에서 6을 뺄 수 없어 백의 자리에서 빌려요 — 11 − 6 = 5.","바른 답은 452예요. 552는 빌려준 자리를 줄이지 않은 값이에요."],"variant_rule":{"alt":[{"stem":"957 − 519 = 448이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 438이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 7에서 9를 뺄 수 없어 십의 자리에서 10을 빌려요 — 17 − 9 = 8.","십의 자리: 1 줄어든 4 − 1 = 3.","바른 답은 438이에요. 448은 빌려준 자리를 줄이지 않은 값이에요."]},{"stem":"667 − 477 = 290이에요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 190이 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 7 − 7 = 0.","십의 자리: 6에서 7을 뺄 수 없어 백의 자리에서 빌려요 — 16 − 7 = 9.","바른 답은 190이에요. 290은 빌려준 자리를 줄이지 않은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
