INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#24','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C7',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X15']::text[],true,'{"seq":24,"concept":"M3-1-u1-C7","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"543 − 348 = 205","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"752 − 173 = 579","mis":"M3-1-u1-X15"},{"t":"984 − 488 = 496","mis":"M3-1-u1-X15"},{"t":"983 − 388 = 595","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","543 − 348은 받아내림을 하면 195예요.","205는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"414 − 287 = 273","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"743 − 176 = 567","mis":"M3-1-u1-X15"},{"t":"513 − 195 = 318","mis":"M3-1-u1-X15"},{"t":"850 − 653 = 197","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","414 − 287은 받아내림을 하면 127이에요.","273은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"556 − 167 = 411","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"562 − 167 = 395","mis":"M3-1-u1-X15"},{"t":"964 − 186 = 778","mis":"M3-1-u1-X15"},{"t":"955 − 557 = 398","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","556 − 167은 받아내림을 하면 389예요.","411은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_c#25','math',3,1,'u1','','g3_1_math_u1_review_c','unit_review','M3-1-u1-C3',4,'essay','teacher','971 − 685를 계산하고, 계산한 값이 맞는지 어림으로 점검하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u1-C3","difficulty":4,"kind":"essay","stem":"971 − 685를 계산하고, 계산한 값이 맞는지 어림으로 점검하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리: 1에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 5 = 6. 십의 자리: 1 줄어든 6에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 16 − 8 = 8. 백의 자리: 1 줄어든 8 − 6 = 2 — 그래서 971 − 685 = 286이에요. 받아내림을 자리마다 작게 표시하고, 어림(약 1000 − 약 700 = 약 300)과 견주어 점검한다.","scoring_points":["자리마다 바르게 계산했는가","받아내림을 표시하거나 빠뜨리지 않는 방법을 썼는가","286을 구하고 어림과 견주었는가"]},"explanation":["일의 자리: 1에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 5 = 6.","십의 자리: 1 줄어든 6에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 16 − 8 = 8.","백의 자리: 1 줄어든 8 − 6 = 2 — 그래서 971 − 685 = 286이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#1','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C1',1,'mc','auto','720 + 103은 얼마인가요?',ARRAY['M3-1-u1-X14']::text[],true,'{"seq":1,"concept":"M3-1-u1-C1","difficulty":1,"kind":"mc","stem":"720 + 103은 얼마인가요?","options":[{"t":"823","correct":true},{"t":"833","mis":"M3-1-u1-X14"},{"t":"813","mis":"M3-1-u1-X14"},{"t":"923","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 3 = 3.","십의 자리: 2 + 0 = 2.","백의 자리: 7 + 1 = 8 — 그래서 720 + 103 = 823이에요."],"variant_rule":{"alt":[{"stem":"580 + 211은 얼마인가요?","options":[{"t":"791","correct":true},{"t":"801","mis":"M3-1-u1-X14"},{"t":"781","mis":"M3-1-u1-X14"},{"t":"891","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 0 + 1 = 1.","십의 자리: 8 + 1 = 9.","백의 자리: 5 + 2 = 7 — 그래서 580 + 211 = 791이에요."]},{"stem":"356 + 341은 얼마인가요?","options":[{"t":"697","correct":true},{"t":"707","mis":"M3-1-u1-X14"},{"t":"687","mis":"M3-1-u1-X14"},{"t":"797","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 6 + 1 = 7.","십의 자리: 5 + 4 = 9.","백의 자리: 3 + 3 = 6 — 그래서 356 + 341 = 697이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
