INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#3','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C2',1,'mc','auto','235 + 645는 얼마인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X03','M3-1-u1-X04']::text[],true,'{"seq":3,"concept":"M3-1-u1-C2","difficulty":1,"kind":"mc","stem":"235 + 645는 얼마인가요?","options":[{"t":"880","correct":true},{"t":"870","mis":"M3-1-u1-X02"},{"t":"970","mis":"M3-1-u1-X03"},{"t":"8710","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 5 + 5 = 10 — 10을 십의 자리로 받아올리고 0을 써요.","십의 자리: 3 + 4 + 1 = 8.","백의 자리: 2 + 6 = 8 — 그래서 235 + 645 = 880이에요."],"variant_rule":{"alt":[{"stem":"269 + 390은 얼마인가요?","options":[{"t":"659","correct":true},{"t":"559","mis":"M3-1-u1-X02"},{"t":"669","mis":"M3-1-u1-X14"},{"t":"649","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 9 + 0 = 9.","십의 자리: 6 + 9 = 15 — 백의 자리로 받아올려요.","백의 자리: 2 + 3 + 1 = 6 — 그래서 269 + 390 = 659예요."]},{"stem":"249 + 318은 얼마인가요?","options":[{"t":"567","correct":true},{"t":"557","mis":"M3-1-u1-X02"},{"t":"657","mis":"M3-1-u1-X03"},{"t":"5517","mis":"M3-1-u1-X04"}],"explanation":["일의 자리: 9 + 8 = 17 — 10을 십의 자리로 받아올리고 7을 써요.","십의 자리: 4 + 1 + 1 = 6.","백의 자리: 2 + 3 = 5 — 그래서 249 + 318 = 567이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#4','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C2',3,'sa','auto','328 + 223을 세로셈으로 계산해요. 십의 자리에서는 2 + 2에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u1-C2","difficulty":3,"kind":"sa","stem":"328 + 223을 세로셈으로 계산해요. 십의 자리에서는 2 + 2에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리: 8 + 3 = 11 — 십의 자리로 1을 받아올려요.","십의 자리: 2 + 2 + 1 = 5.","받아올림한 1을 빠뜨리면 4가 되어 틀려요."],"variant_rule":{"alt":[{"stem":"715 + 238을 세로셈으로 계산해요. 십의 자리에서는 1 + 3에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리: 5 + 8 = 13 — 십의 자리로 1을 받아올려요.","십의 자리: 1 + 3 + 1 = 5.","받아올림한 1을 빠뜨리면 4가 되어 틀려요."]},{"stem":"305 + 146을 세로셈으로 계산해요. 십의 자리에서는 0 + 4에 일의 자리에서 받아올림한 1을 더해요. 그 값은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["일의 자리: 5 + 6 = 11 — 십의 자리로 1을 받아올려요.","십의 자리: 0 + 4 + 1 = 5.","받아올림한 1을 빠뜨리면 4가 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
