INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#13','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C6',1,'mc','auto','839 − 283은 얼마인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X14']::text[],true,'{"seq":13,"concept":"M3-1-u1-C6","difficulty":1,"kind":"mc","stem":"839 − 283은 얼마인가요?","options":[{"t":"556","correct":true},{"t":"656","mis":"M3-1-u1-X07"},{"t":"566","mis":"M3-1-u1-X14"},{"t":"546","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 9 − 3 = 6.","십의 자리: 3에서 8을 뺄 수 없어 백의 자리에서 빌려요 — 13 − 8 = 5.","백의 자리: 1 줄어든 7 − 2 = 5 — 그래서 839 − 283 = 556이에요."],"variant_rule":{"alt":[{"stem":"275 − 107은 얼마인가요?","options":[{"t":"168","correct":true},{"t":"172","mis":"M3-1-u1-X07"},{"t":"178","mis":"M3-1-u1-X08"},{"t":"158","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 5에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 15 − 7 = 8.","십의 자리: 1 줄어든 6 − 0 = 6.","백의 자리: 2 − 1 = 1 — 그래서 275 − 107 = 168이에요."]},{"stem":"938 − 360은 얼마인가요?","options":[{"t":"578","correct":true},{"t":"638","mis":"M3-1-u1-X07"},{"t":"678","mis":"M3-1-u1-X08"},{"t":"588","mis":"M3-1-u1-X14"}],"explanation":["일의 자리: 8 − 0 = 8.","십의 자리: 3에서 6을 뺄 수 없어 백의 자리에서 빌려요 — 13 − 6 = 7.","백의 자리: 1 줄어든 8 − 3 = 5 — 그래서 938 − 360 = 578이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#14','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C6',2,'sa','auto','590 − 316을 세로셈으로 계산해요. 일의 자리 0에서 6을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 6을 빼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-1-u1-C6","difficulty":2,"kind":"sa","stem":"590 − 316을 세로셈으로 계산해요. 일의 자리 0에서 6을 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 6을 빼나요? 숫자로 쓰세요.","answer":["10"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 0 + 10 = 10이 돼요.","10 − 6 = 4, 십의 자리는 1 줄어요."],"variant_rule":{"alt":[{"stem":"793 − 689를 세로셈으로 계산해요. 일의 자리 3에서 9를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 9를 빼나요? 숫자로 쓰세요.","answer":["13"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 3 + 10 = 13이 돼요.","13 − 9 = 4, 십의 자리는 1 줄어요."]},{"stem":"877 − 329를 세로셈으로 계산해요. 일의 자리 7에서 9를 뺄 수 없어 십의 자리에서 받아내림해요. 받아내림한 뒤 일의 자리는 몇에서 9를 빼나요? 숫자로 쓰세요.","answer":["17"],"explanation":["십 모형 1개를 일 모형 10개로 바꿔요.","일의 자리는 7 + 10 = 17이 돼요.","17 − 9 = 8, 십의 자리는 1 줄어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#15','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C6',3,'ox','auto','681 − 436 = 255예요.',ARRAY['M3-1-u1-X08']::text[],true,'{"seq":15,"concept":"M3-1-u1-C6","difficulty":3,"kind":"ox","stem":"681 − 436 = 255예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 245가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"mis":"M3-1-u1-X08","explanation":["일의 자리: 1에서 6을 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 6 = 5.","십의 자리: 1 줄어든 7 − 3 = 4.","바른 답은 245예요. 255는 빌려준 자리를 줄이지 않은 값이에요."],"variant_rule":{"alt":[{"stem":"520 − 105 = 425예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 415가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 0에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 5 = 5.","십의 자리: 1 줄어든 1 − 0 = 1.","바른 답은 415예요. 425는 빌려준 자리를 줄이지 않은 값이에요."]},{"stem":"751 − 322 = 439예요.","answer":"X","reason_options":[{"t":"받아내림하고 빌려준 윗자리를 1 줄이면 429가 되어서","correct":true},{"t":"자리마다 뺄 수 있는 대로 뺐으니 맞아서","mis":"M3-1-u1-X08"}],"explanation":["일의 자리: 1에서 2를 뺄 수 없어 십의 자리에서 10을 빌려요 — 11 − 2 = 9.","십의 자리: 1 줄어든 4 − 2 = 2.","바른 답은 429예요. 439는 빌려준 자리를 줄이지 않은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
