INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#19','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C8',1,'mc','auto','비사치기에서 배로 359점, 이마로 387점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?',ARRAY['M3-1-u1-X02','M3-1-u1-X05','M3-1-u1-X14']::text[],true,'{"seq":19,"concept":"M3-1-u1-C8","difficulty":1,"kind":"mc","stem":"비사치기에서 배로 359점, 이마로 387점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"746점","correct":true},{"t":"636점","mis":"M3-1-u1-X02"},{"t":"646점","mis":"M3-1-u1-X05"},{"t":"756점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 359 + 387.","십의 자리: 5 + 8 + 1 = 14 — 백의 자리로 받아올려요.","359 + 387 = 746점이에요."],"variant_rule":{"alt":[{"stem":"비사치기에서 어깨로 465점, 무릎으로 276점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"741점","correct":true},{"t":"631점","mis":"M3-1-u1-X02"},{"t":"641점","mis":"M3-1-u1-X05"},{"t":"751점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 465 + 276.","십의 자리: 6 + 7 + 1 = 14 — 백의 자리로 받아올려요.","465 + 276 = 741점이에요."]},{"stem":"비사치기에서 손등으로 318점, 머리로 492점을 얻었어요. 두 방법으로 얻은 점수는 모두 몇 점인가요?","options":[{"t":"810점","correct":true},{"t":"700점","mis":"M3-1-u1-X02"},{"t":"710점","mis":"M3-1-u1-X05"},{"t":"820점","mis":"M3-1-u1-X14"}],"explanation":["모은 점수는 덧셈 — 318 + 492.","십의 자리: 1 + 9 + 1 = 11 — 백의 자리로 받아올려요.","318 + 492 = 810점이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#20','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C8',2,'mc','auto','줄넘기를 도윤이는 943번, 지유는 438번 했어요. 도윤이는 지유보다 몇 번 더 했나요?',ARRAY['M3-1-u1-X12','M3-1-u1-X07','M3-1-u1-X14']::text[],true,'{"seq":20,"concept":"M3-1-u1-C8","difficulty":2,"kind":"mc","stem":"줄넘기를 도윤이는 943번, 지유는 438번 했어요. 도윤이는 지유보다 몇 번 더 했나요?","options":[{"t":"505번","correct":true},{"t":"1381번","mis":"M3-1-u1-X12"},{"t":"515번","mis":"M3-1-u1-X07"},{"t":"495번","mis":"M3-1-u1-X14"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 943 − 438.","일의 자리: 3에서 8을 뺄 수 없어 십의 자리에서 10을 빌려요 — 13 − 8 = 5.","943 − 438 = 505 — 505번이에요."],"variant_rule":{"alt":[{"stem":"줄넘기를 도윤이는 972번, 지유는 465번 했어요. 도윤이는 지유보다 몇 번 더 했나요?","options":[{"t":"507번","correct":true},{"t":"1437번","mis":"M3-1-u1-X12"},{"t":"513번","mis":"M3-1-u1-X07"},{"t":"517번","mis":"M3-1-u1-X08"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 972 − 465.","일의 자리: 2에서 5를 뺄 수 없어 십의 자리에서 10을 빌려요 — 12 − 5 = 7.","972 − 465 = 507 — 507번이에요."]},{"stem":"줄넘기를 도윤이는 290번, 지유는 187번 했어요. 도윤이는 지유보다 몇 번 더 했나요?","options":[{"t":"103번","correct":true},{"t":"477번","mis":"M3-1-u1-X12"},{"t":"117번","mis":"M3-1-u1-X07"},{"t":"113번","mis":"M3-1-u1-X08"}],"explanation":["몇 더 많은지 구하니 뺄셈이에요 — 290 − 187.","일의 자리: 0에서 7을 뺄 수 없어 십의 자리에서 10을 빌려요 — 10 − 7 = 3.","290 − 187 = 103 — 103번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
