INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#22','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C8',3,'mc','auto','배 359점과 이마 387점을 얻었어요. 이 점수로 축구공(755점)을 바꿀 수 있나요?',ARRAY['M3-1-u1-X13','M3-1-u1-X15']::text[],true,'{"seq":22,"concept":"M3-1-u1-C8","difficulty":3,"kind":"mc","stem":"배 359점과 이마 387점을 얻었어요. 이 점수로 축구공(755점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"배 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 359 + 387 = 746.","746점과 축구공 755점을 견주면 746 < 755예요.","그래서 바꿀 수 없어요."],"variant_rule":{"alt":[{"stem":"손등 318점과 머리 492점을 얻었어요. 이 점수로 보드게임(816점)을 바꿀 수 있나요?","options":[{"t":"바꿀 수 없어요","correct":true},{"t":"바꿀 수 있어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"손등 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 318 + 492 = 810.","810점과 보드게임 816점을 견주면 810 < 816이에요.","그래서 바꿀 수 없어요."]},{"stem":"발등 234점과 어깨 465점을 얻었어요. 이 점수로 줄넘기(543점)를 바꿀 수 있나요?","options":[{"t":"바꿀 수 있어요","correct":true},{"t":"바꿀 수 없어요","mis":"M3-1-u1-X13"},{"t":"점수를 모르니 알 수 없어요","mis":"M3-1-u1-X15"},{"t":"발등 점수만 보면 돼요","mis":"M3-1-u1-X13"}],"explanation":["두 점수를 더해요 — 234 + 465 = 699.","699점과 줄넘기 543점을 견주면 699 > 543이에요.","그래서 바꿀 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
