INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#24','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C7',4,'error','auto','다음 중 계산이 틀린 것은 어느 것인가요?',ARRAY['M3-1-u1-X07','M3-1-u1-X15']::text[],true,'{"seq":24,"concept":"M3-1-u1-C7","difficulty":4,"kind":"error","stem":"다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"915 − 697 = 382","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"861 − 282 = 579","mis":"M3-1-u1-X15"},{"t":"818 − 199 = 619","mis":"M3-1-u1-X15"},{"t":"870 − 181 = 689","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","915 − 697은 받아내림을 하면 218이에요.","382는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"633 − 384 = 351","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"962 − 285 = 677","mis":"M3-1-u1-X15"},{"t":"873 − 296 = 577","mis":"M3-1-u1-X15"},{"t":"791 − 493 = 298","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","633 − 384는 받아내림을 하면 249예요.","351은 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]},{"stem":"이번에는 다른 수예요. 다음 중 계산이 틀린 것은 어느 것인가요?","options":[{"t":"884 − 198 = 714","correct":true,"mis_target":"M3-1-u1-X07"},{"t":"484 − 289 = 195","mis":"M3-1-u1-X15"},{"t":"762 − 465 = 297","mis":"M3-1-u1-X15"},{"t":"844 − 589 = 255","mis":"M3-1-u1-X15"}],"explanation":["하나씩 다시 계산해 봐요.","884 − 198은 받아내림을 하면 686이에요.","714는 뺄 수 없는 자리에서 거꾸로 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u1_review_d#25','math',3,1,'u1','','g3_1_math_u1_review_d','unit_review','M3-1-u1-C3',4,'essay','teacher','379 + 389를 계산하고, 계산한 값이 맞는지 어림으로 점검하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u1-C3","difficulty":4,"kind":"essay","stem":"379 + 389를 계산하고, 계산한 값이 맞는지 어림으로 점검하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 일의 자리: 9 + 9 = 18 — 10을 십의 자리로 받아올리고 8을 써요. 십의 자리: 7 + 8 + 1 = 16 — 백의 자리로 받아올려요. 백의 자리: 3 + 3 + 1 = 7 — 그래서 379 + 389 = 768이에요. 받아올림을 자리마다 작게 표시하고, 어림(약 400 + 약 400 = 약 800)과 견주어 점검한다.","scoring_points":["자리마다 바르게 계산했는가","받아올림을 표시하거나 빠뜨리지 않는 방법을 썼는가","768을 구하고 어림과 견주었는가"]},"explanation":["일의 자리: 9 + 9 = 18 — 10을 십의 자리로 받아올리고 8을 써요.","십의 자리: 7 + 8 + 1 = 16 — 백의 자리로 받아올려요.","백의 자리: 3 + 3 + 1 = 7 — 그래서 379 + 389 = 768이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
